/* ---------------- updates ----------------
   The service worker is cache-first, which is what makes the app open with no
   signal — and what can strand you on a broken build. Until now the only way
   forward was to wait for the worker to notice, and a session in progress
   deferred that indefinitely. So: a check you can run yourself, and one that
   runs at startup and tells you rather than deciding for you.

   version.json is tiny and deliberately not cached (the worker passes it
   straight to the network), so the check costs a few bytes rather than the
   611 KB shell. */
export async function fetchLatestVersion() {
  try {
    const r = await fetch('version.json?t=' + Date.now(), { cache: 'no-store' });
    if (!r.ok) return null;
    const v = await r.json();
    return v && v.version ? v : null;
  } catch (e) { return null; }   // offline: nothing to say
}

/* Graceful first: let the waiting worker take over. If there is none — the
   usual case when the shell is stale but the worker already activated — clear
   the caches and reload, which always works. */
export let updateAsked = false;   // the lifter tapped Update: the worker taking over should reload, even on a first session
async function applyUpdate() {
  updateAsked = true;
  toast('Updating…');
  try { await flush(); } catch (e) { /* the reload goes ahead; pagehide tries once more */ }
  try {
    const reg = await navigator.serviceWorker.getRegistration();
    if (reg) {
      await reg.update().catch(() => {});
      if (reg.waiting) { reg.waiting.postMessage({ type: 'SKIP_WAITING' }); return; }
    }
    for (const k of await caches.keys()) await caches.delete(k);
  } catch (e) { /* fall through to the reload */ }
  location.reload();
}

function updateAvailableDlg(latest) {
  modal({
    title: 'Update available',
    body: `<div class="sub" style="margin-top:0">You're on <b>v${esc(APP_VERSION)}</b>. <b>v${esc(latest.version)}</b> is ready.</div>
      ${S.active ? `<div class="sub" style="margin-top:10px;color:var(--gold)">Your workout in progress is saved and will still be here afterwards.</div>` : ''}`,
    foot: `<button class="btn ghost" data-close>Later</button><button class="btn primary" id="upGo">Update now</button>`,
    onOpen: bg => { $('#upGo', bg).onclick = () => { closeModal(); applyUpdate(); }; },
  });
}

/* silent: say nothing when already current — that is the startup case. */
export async function checkForUpdate(silent) {
  const latest = await fetchLatestVersion();
  if (!latest) { if (!silent) toast("Couldn't reach the server — you may be offline"); return false; }
  if (latest.version === APP_VERSION) { if (!silent) toast(`You're on the latest version (v${APP_VERSION})`, 'green'); return false; }
  updateAvailableDlg(latest);
  return true;
}


