function renderPage() {
  bust();
  if (page === 'analytics' && analyticsTab === 'body') { setAnalyticsTab('exercises'); setPage('health'); }   // Body moved to Health (D12)
  const lit = NAV_TAB[page] || page;
  document.querySelectorAll('#nav [data-page]').forEach(b => {
    b.classList.toggle('active', b.dataset.page === lit);
    if (b.dataset.page === lit) b.setAttribute('aria-current', 'page'); else b.removeAttribute('aria-current');
  });
  const v = $('#view');
  if (page === 'home') v.innerHTML = viewHome();
  else if (page === 'calendar') v.innerHTML = viewCalendar();
  else if (page === 'workout') v.innerHTML = viewWorkout();
  else if (page === 'analytics') v.innerHTML = viewAnalytics();
  else if (page === 'meets') v.innerHTML = viewMeets();
  else if (page === 'health') v.innerHTML = viewHealth();
  document.documentElement.toggleAttribute('data-w98-work', page === 'workout' && !!S.active && S.active.kind !== 'cardio');
  wire();
  a11yPass(v);
  maybeWhatsNew();
  maybePoolNotice();
}


