/* ============================================================
   WHAT'S NEW — roadmap A2
   CHANGELOG.md sits at the root (the app loads it) and is precached with the
   shell. After an update, the entries newer than the last version seen are
   shown once. Never mid-workout — it waits for the session to end — and never
   on a fresh install. If the file can't be loaded, it says nothing and tries
   again next launch; it never blocks the app.
   ============================================================ */
function verCmp(a, b) {
  const pa = String(a).split('.').map(Number), pb = String(b).split('.').map(Number);
  for (let i = 0; i < 3; i++) { const d = (pa[i] || 0) - (pb[i] || 0); if (d) return d; }
  return 0;
}
let _changelog = null;
function loadChangelog() {
  if (!_changelog) {
    _changelog = fetch('CHANGELOG.md').then(r => { if (!r.ok) throw new Error('HTTP ' + r.status); return r.text(); })
      .catch(e => { _changelog = null; throw e; });
  }
  return _changelog;
}
/* Entries start at "## "; everything above the first one (the note on how to
   keep the file) is for whoever edits it, not for the app. */
function parseChangelog(text) {
  const out = [];
  String(text).replace(/\r\n?/g, '\n').split('\n').forEach(line => {
    if (line.startsWith('## ')) {
      const head = line.slice(3).trim();
      const m = head.match(/^(\d+\.\d+\.\d+)/);
      out.push({ head, version: m ? m[1] : null, lines: [] });
    } else if (out.length) out[out.length - 1].lines.push(line);
  });
  return out;
}
/* The small subset the changelog uses: "- " bullets (indented lines carry
   on the bullet), paragraphs, **bold**, `code`, [links](url). Escaped first,
   so nothing in the file can become markup it didn't ask for. */
function mdInline(s) {
  return esc(s)
    .replace(/\*\*(.+?)\*\*/g, '<b>$1</b>')
    .replace(/`([^`]+)`/g, '<code>$1</code>')
    .replace(/\[([^\]]+)\]\((https?:[^)\s]+)\)/g, '<a href="$2" target="_blank" rel="noopener">$1</a>');
}
function mdBlock(lines) {
  const blocks = [];
  let cur = null;
  lines.forEach(l => {
    if (!l.trim() || /^-{3,}\s*$/.test(l)) { cur = null; return; }
    if (/^- /.test(l)) { cur = { li: true, text: l.slice(2) }; blocks.push(cur); return; }
    if (cur) cur.text += ' ' + l.trim();
    else { cur = { li: false, text: l.trim() }; blocks.push(cur); }
  });
  let html = '', inList = false;
  blocks.forEach(b => {
    if (b.li && !inList) { html += '<ul class="wn-list">'; inList = true; }
    if (!b.li && inList) { html += '</ul>'; inList = false; }
    html += b.li ? `<li>${mdInline(b.text)}</li>` : `<p>${mdInline(b.text)}</p>`;
  });
  return html + (inList ? '</ul>' : '');
}
function changelogHtml(entries) {
  return entries.map(e => `<section class="wn-entry"><h3>${mdInline(e.head)}</h3>${mdBlock(e.lines)}</section>`).join('');
}
function showChangelog(title, entries, note) {
  modal({
    title,
    body: `${note ? `<div class="sub" style="margin-bottom:8px">${esc(note)}</div>` : ''}${changelogHtml(entries)}`,
    foot: `<button class="btn primary wide" data-close>Got it</button>`,
  });
}
/* Settings / Help menu: the whole thing, any time. */
function openWhatsNew() {
  loadChangelog()
    .then(t => showChangelog("What's new", parseChangelog(t), `You're on ${APP_VERSION}.`))
    .catch(() => toast("Couldn't load the changelog — try again when you're online"));
}
/* The after-update sheet. Armed after first paint; re-checked on each render,
   so a sheet held back by a live session appears once it's finished. */
export function maybeWhatsNew() {
  if (!whatsNewArmed || whatsNewBusy || S.active || modalStack.length) return;
  const seen = S.settings.lastSeenVersion;
  if (seen === APP_VERSION) { setWhatsNewArmed(false); return; }
  setWhatsNewBusy(true);
  loadChangelog().then(text => {
    setWhatsNewBusy(false);
    if (S.active || modalStack.length) return;          // try again on a later render
    const all = parseChangelog(text);
    /* No record at all means the app predates this screen: show this
       version's entry rather than the whole history. */
    const newer = all.filter(e => e.version && verCmp(e.version, APP_VERSION) <= 0
      && (seen ? verCmp(e.version, seen) > 0 : e.version === APP_VERSION));
    S.settings.lastSeenVersion = APP_VERSION;
    save();
    setWhatsNewArmed(false);
    if (newer.length) showChangelog(`What's new in ${APP_VERSION}`, newer);
  }).catch(() => { setWhatsNewBusy(false); setWhatsNewArmed(false); });   // offline: next launch
}

