function viewHome() {
  const ci = checkinFor(today());
  const now = new Date();
  const hr = now.getHours();
  const greet = hr < 12 ? 'Good morning' : hr < 18 ? 'Good afternoon' : 'Good evening';

  // today's workouts
  const todays = S.workouts.filter(w => w.date === today());
  const planned = todays.filter(w => w.status === 'planned');
  const done = todays.filter(w => w.status === 'completed' && w.kind !== 'mobility');   // mobility has its own line (E5)

  let scheduleHtml;
  if (S.active) {
    scheduleHtml = `<div class="row between">
        <div><div style="font-weight:700">${esc(S.active.name)}</div>
        <div class="sub">In progress · ${S.active.exercises.length} exercise${S.active.exercises.length === 1 ? '' : 's'}</div></div>
        <button class="btn primary sm" data-go="workout">Resume</button>
      </div>`;
  } else if (planned.length) {
    scheduleHtml = planned.map(p => `
      <div class="row between" style="margin-bottom:8px">
        <div class="grow"><div style="font-weight:700">${esc(p.name)}${autoBlock(p) ? ' <span class="chip" title="Loads are set from your RIR when you start">⟳ AUTO</span>' : ''}</div>
        <div class="sub">${p.exercises.length} exercise${p.exercises.length === 1 ? '' : 's'} planned</div></div>
        <div class="row" style="gap:6px"><button class="btn ghost sm" data-miss="${p.id}">${missBtn(p)}</button>
        <button class="btn primary sm" data-start-planned="${p.id}">Start</button></div>
      </div>
      <div>${p.exercises.map(e => `<div class="exline"><span>${exNameHtml(e)}</span>
          <span class="muted mono" style="white-space:nowrap">${setSummary(e)}</span></div>`).join('')}</div>`)
      .join('<div class="hr"></div>');
  } else if (done.length) {
    scheduleHtml = done.map(d => `<div class="row between">
        <div><div style="font-weight:700">${esc(d.name)} <span class="chip green">DONE</span>${srcChip(d)}</div>
        <div class="sub">${d.exercises.length} exercises · ${wt(totalVolume(d), 0)} volume</div></div>
        <button class="btn ghost sm" data-view-workout="${d.id}">View</button>
      </div>`).join('<div class="hr"></div>');   // two sessions in a day ran into each other
  } else {
    scheduleHtml = `<div class="row between">
        <div><div style="font-weight:700">Rest day</div><div class="sub">Nothing scheduled for today</div></div>
        <button class="btn sm" data-go="calendar">Plan one</button>
      </div>`;
  }

  // week stats
  const wk = last7();
  const avgSleep = avg(wk.map(c => c.sleepH).filter(Boolean));
  const bws = S.checkins.filter(c => c.weight > 0).sort((a, b) => a.date < b.date ? -1 : 1);
  const bwNow = bws.length ? bws[bws.length - 1].weight : 0;
  const bw7 = bws.filter(c => daysBetween(c.date, today()) <= 7);
  const bwDelta = bw7.length > 1 ? bwNow - bw7[0].weight : 0;
  const sessions7 = S.workouts.filter(w => w.status === 'completed' && w.kind !== 'mobility' && daysBetween(w.date, today()) <= 7).length;

  /* Today's session leads Home for anyone who is training with Ironlog — a
     workout in progress, something planned today, or a log with history
     (00-D1). It used to sit under the About card, the backup nudge, the
     check-in and the week's numbers, a screen and a half down. Someone who
     hasn't started yet still gets the About card first (home-landing-spec). */
  const trainFirst = !!(S.active || planned.length || S.workouts.some(w => w.status === 'completed'));
  const training = `<div class="sechead"${trainFirst ? ' style="margin-top:0"' : ''}><h2>Today's training</h2>
    ${!S.active && !planned.length ? `<button class="btn xs" id="quickStart">Start blank</button>` : ''}
  </div>
  <div class="card"${trainFirst ? ' style="margin-bottom:13px"' : ''}>${scheduleHtml}</div>`;

  return `
  <h1>${greet}</h1>
  <div class="sub" style="margin-bottom:14px">${new Date().toLocaleDateString(undefined, { weekday: 'long', month: 'long', day: 'numeric' })}${streak() > 1 ? ` · 🔥 ${streak()} day check-in streak` : ''}</div>
  ${trainFirst ? training : ''}
  ${aboutCard()}
  ${backupCard()}
  ${eventCountdown()}
  ${runInLine(today())}
  ${mobilityHomeLine()}
  ${coachHomeCard()}

  <div class="hero">
    <div class="row between">
      <div>
        <div class="eyebrow">Daily check-in</div>
        <div style="font-weight:750;font-size:17px;margin-top:3px">${ci ? 'Logged for today' : 'Not logged yet'}</div>
      </div>
      <button class="btn ${ci ? '' : 'primary'}" id="checkinBtn">${ci ? 'Edit' : 'Check in'}</button>
    </div>
    ${ci ? `<div class="checkin-done">
        <div class="ci-tile"><div class="k">Weight</div><div class="v">${ci.weight ? wt(ci.weight) : '—'}</div></div>
        <div class="ci-tile"><div class="k">Sleep</div><div class="v">${ci.sleepH ? ci.sleepH + 'h' : '—'}</div></div>
        <div class="ci-tile"><div class="k">Energy</div><div class="v">${ci.energy || '—'}${ci.energy ? '/5' : ''}</div></div>
        <div class="ci-tile"><div class="k">Soreness</div><div class="v">${ci.soreness || '—'}${ci.soreness ? '/5' : ''}</div></div>
      </div>${ci.notes ? `<div class="sub" style="margin-top:9px">“${esc(ci.notes)}”</div>` : ''}` : ''}
  </div>

  <div class="stats grid3" style="margin-bottom:13px">
    <div class="stat"><div class="k">Bodyweight</div><div class="v">${bwNow ? w(bwNow) : '—'}</div>
      <div class="d">${bwDelta ? (bwDelta > 0 ? '▲ ' : '▼ ') + wt(Math.abs(bwDelta)) + ' / 7d' : 'no change'}</div></div>
    <div class="stat"><div class="k">Sleep avg</div><div class="v">${avgSleep ? nice(avgSleep) : '—'}<small>h</small></div><div class="d">last 7 days</div></div>
    <div class="stat"><div class="k">Sessions</div><div class="v">${sessions7}</div><div class="d">last 7 days</div></div>
  </div>

  ${trainFirst ? '' : training}

  <div class="sechead"><h2>Goals</h2><button class="btn xs" id="addGoal">+ Add</button></div>
  <div class="card">${S.goals.length ? S.goals.map(goalRow).join('') :
      `<div class="empty"><span class="big">◎</span>No goals yet.<br>Add one to track progress toward a number.</div>`}</div>
  `;
}

/* The nearest event inside two weeks, as a card that opens meet day (D12). */
function eventCountdown() {
  const m = [...(S.meets || [])].filter(x => x.date && daysBetween(today(), x.date) >= 0 && daysBetween(today(), x.date) <= 14)
    .sort((a, b) => a.date < b.date ? -1 : 1)[0];
  if (!m) return '';
  const d = daysBetween(today(), m.date);
  return `<div class="card" style="margin-bottom:13px;border-color:var(--gold)">
    <div class="row between">
      <div class="grow"><div class="eyebrow" style="color:var(--gold)">★ ${d === 0 ? 'Today' : `In ${d} day${d === 1 ? '' : 's'}`}</div>
        <div style="font-weight:700;margin-top:3px">${esc(m.name)}</div>
        <div class="sub">${esc(eventType(m).label)} · ${fmtDate(m.date, { weekday: 'short', month: 'short', day: 'numeric' })}</div></div>
      <button class="btn primary sm" data-meetday="${m.id}">Meet day</button>
    </div>
  </div>`;
}


/* ---------------- debug mode: show the working (E11) ----------------
   r&d/specs/debug-mode-spec.md. Off by default. why() puts a small "how?"
   beside a worked-out number; tapping it runs that kind's explainer, which
   redoes the sum step by step and then checks itself against the app's own
   function. Nothing is built until the tap, and nothing is ever written. */

const rirText = rpe => rpe == null ? 'no RIR logged' : `RIR ${nice(rpeToRir(rpe))} (RPE ${nice(rpe)})`;
/* Where targetRirFor's answer came from: the note, the block, or the default. */
function targetRirSource(e, blockRir) {
  const n = String((e && e.notes) || '').toLowerCase();
  const m = n.match(/stop (\d) shy/) || n.match(/rir\s*(\d)/) || n.match(/@\s*(\d)\b/);
  return m ? `the exercise note ("${m[0]}")` : blockRir != null ? 'the training block' : 'the default';
}

Object.assign(WHY, {
  bpath: { label: 'bar path from video', fn: v => {
    const c = v && v.cal;
    if (!c) return null;
    const t = trace('bar speed from video');
    t.step('Plate diameter', `${c.plateMm} mm`, 'what the scale comes from');
    t.step('Plate radius in the frame', `${(c.r * 100).toFixed(1)}% of frame height`, c.how ? `outer edge — ${c.how}` : 'from the circle you confirmed');
    const mPerH = (c.plateMm / 1000) / (2 * c.r);
    t.step('Scale', `${c.plateMm} mm ÷ (2 × ${c.r}) = ${mPerH.toFixed(3)} m per frame height`, 'so 1% of the frame height is ' + (mPerH * 1000 / 100).toFixed(1) + ' mm');
    t.step('Frames', `${c.frames} at ${BP.hz} a second`, 'stepped through by seeking, not playing');
    t.step('Plate found on', `${Math.round(c.coverage * 100)}%`, c.gaps && c.gaps.length ? bpGapText(c) : 'short gaps filled by a straight line');
    (v.reps || []).slice(0, 3).forEach((r, i) => t.step(`Rep ${i + 1}`, `${(r.rom * 100).toFixed(0)} cm up in ${r.con != null ? r.con.toFixed(1) + ' s' : '—'} → ${r.v.toFixed(2)} m/s`, 'mean speed of the way up, from Slew\'s engine (the same one Measure uses)'));
    t.note('An estimate: the camera must be square to the plate. Every 15° off reads a few % short.');
    t.result('Best rep', `${v.best.toFixed(2)} m/s`);
    return t;
  } },
  vol: { label: 'weekly sets', fn: k => {
    const { weeks, by } = weeklySets();
    const wk = weeks[weeks.length - 1], rows = hardSetRows(wk, '9999').filter(r => r.k === k), t = volTarget(k);
    const tr = trace(`${MUSCLES[k]} · hard sets this week`);
    tr.step('Week', `from Monday ${fmtDate(wk, { day: 'numeric', month: 'short' })}`);
    tr.note('Counted: done working sets with reps, time or distance; warm-ups and RIR 5+ left out; a drop after the first set of its chain is ½. The muscle gets 1 if it is the lift\'s main muscle (within 80% of the biggest share), ½ if its share is 0.20 or more.');
    let sum = 0;
    rows.forEach(r => { sum += r.n; tr.step(`${r.name}${r.live ? ' (live)' : ''} · ${setLine(r.set)}`, setsTxt(r.n), `set ${nice(r.worth)} × muscle ${nice(r.credit)}`); });
    if (!rows.length) tr.note('No sets count for this muscle this week.');
    tr.result('Hard sets', setsTxt(sum), `range ${t.mev}–${t.mrv}, ${volStatus(sum, t, new Date().getDay() !== 0).word}`);
    return tr.check('Hard sets', sum, (by[k] || [0])[weeks.length - 1] || 0, setsTxt);
  } },
  e1: { label: 'estimated 1RM', fn: (kg, r, rpe) => {
    const t = trace('estimated 1RM');
    t.step('Weight', wt(kg)).step('Reps', r);
    const rir = e1Rir(rpe), eff = (r || 0) + rir;
    t.step('Effort', rpe == null ? 'not logged' : rirText(rpe), rpe == null ? 'counted as 0 reps left' : rpe > 10 ? 'off the scale, so counted as 0 reps left'
      : rpe < 5 ? 'past RIR 5, counted as 5 — guesses that far out aren\'t reliable' : 'RIR = 10 − RPE');
    t.step('Reps the set was worth', `${r} + ${nice(rir)} = ${nice(eff)}`, 'reps done + reps left');
    let mine;
    if (!kg || !r) { mine = 0; t.note('No weight or no reps: no estimate.'); }
    else if (eff <= 1) { mine = kg; t.step('Rule', 'a true single', 'worth 1 rep or less, so the weight is the 1RM'); }
    else {
      const c = Math.min(eff, 12);
      if (eff > 12) t.step('Cap', `${nice(eff)} → 12`, 'Epley drifts past 12 reps, so it stops there');
      mine = kg * (1 + c / 30);
      t.step('Epley', `${nice(dw(kg, 2))} × (1 + ${nice(c)} ÷ 30)`, 'weight × (1 + reps ÷ 30)');
    }
    t.result('Estimated 1RM', wt(mine));
    return t.check('Estimated 1RM', mine, e1rm(kg, r, rpe), v => wt(v));
  } },

  rir: { label: 'RIR and RPE', fn: rpe => {
    const t = trace(`RPE ${nice(rpe)} ↔ RIR`);
    t.step('Stored', `RPE ${nice(rpe)}`, 'Ironlog stores RPE; every effort sum uses it');
    t.step('Shown', `10 − ${nice(rpe)} = ${nice(10 - rpe)}`, 'RIR = 10 − RPE, reps left in the tank');
    t.step('Typing it back', `10 − ${nice(10 - rpe)} = RPE ${nice(rpe)}`, 'RPE = 10 − RIR, so nothing is lost either way');
    t.note('In the e1RM the reps left are added to the reps done: 100 × 5 at RIR 2 is worth 7 reps.');
    t.result('RIR', nice(10 - rpe));
    return t.check('RIR', 10 - rpe, rpeToRir(rpe)).check('RPE back', rirToRpe(10 - rpe), rpe);
  } },

  pr: { label: 'PR', fn: (woId, i) => {
    const wo = S.workouts.find(x => x.id === woId), p = wo && prsFor(wo)[i];
    if (!p) return null;
    const t = trace(`PR — ${p.name || 'lift'}`);
    t.step('Session', fmtDate(wo.date, { weekday: 'short', day: 'numeric', month: 'short', year: 'numeric' }), wo.name || '');
    if (p.key) {
      const split = keyPR(p.key).map(id => modLabel(id).toLowerCase());
      t.step('Record line', leafName(p.key), [keyVariantLabel(p.key), `key ${p.key}`].filter(Boolean).join(' · '));
      t.step('Kept apart by', split.length ? split.join(', ') : 'nothing extra', split.length ? 'modifiers that split the PR line (D10)' : 'no chains, bands, slingshot or equipped');
    }
    if (p.label) {
      t.step('Record', p.label, p.what || '');
      t.note('Holds, carries, races, time caps and stone series each keep their own record: the best hold or time at a weight, furthest at a weight, most reps in the cap. This beat the best one dated before this session.');
      return t.result('PR', 'yes');
    }
    const e = wo.exercises.find(x => exKey(x) === p.key);
    const sets = e ? e.sets.filter(s => s.done && isPRSet(s) && s.r > 0) : [];
    t.head('This session');
    t.note('Warm-ups and drop sets never count; only done sets with reps.');
    sets.forEach((s, k) => t.step(`Set ${k + 1}`, setLine(s), s.w > 0 ? `e1RM ${wt(e1rm(s.w, s.r, s.rpe))}` : 'bodyweight'));
    const best = sets.length ? bestSetOf(sets) : null;
    if (best) t.step('Best set', setLine(best), best.w > 0 ? 'highest e1RM' : 'most reps (nothing loaded)');
    const st = statsFor(p.key, wo);
    t.head('History before this session');
    if (!st) return t.note('Nothing logged before: a first session sets the marks, it isn\'t a PR.');
    t.step('Sets counted', st.totalSets, S.settings.prCountEst !== false ? 'backfilled sets count (Settings)' : 'backfilled sets left out (Settings)');
    let mine;
    if (best && best.w > 0) {
      t.step('Best before', `${setLine(st.best)} · ${fmtDate(st.best.date)}`, `e1RM ${wt(st.best.e1)}`);
      const now = e1rm(best.w, best.r, best.rpe);
      mine = now > st.best.e1;
      t.step('Compare', `${wt(now)} ${mine ? '>' : '≤'} ${wt(st.best.e1)}`, 'beats it only if strictly higher');
    } else if (best) {
      t.step('Best before', st.bestBw ? `${st.bestBw.r} reps · ${fmtDate(st.bestBw.date)}` : 'no bodyweight sets', 'bodyweight sets only race bodyweight sets');
      mine = !!st.bestBw && best.r > st.bestBw.r;
      t.step('Compare', st.bestBw ? `${best.r} ${mine ? '>' : '≤'} ${st.bestBw.r}` : '—');
    }
    t.result('PR', mine ? 'yes' : 'no');
    return t.check('PR', mine ? 'yes' : 'no', best && beatsBest(st, best.w, best.r, best.rpe) ? 'yes' : 'no');
  } },

  rank: { label: 'strength tier', fn: key => {
    const name = leafName(key), t = trace(`${name} — tier`);
    const src = bodyweightSource(), bw = bodyweightKg(), st = statsFor(key), raw = STD[name];
    t.step('Bodyweight', wt(bw), src.from === 'checkin' ? `check-in ${fmtDate(src.date)}` : src.from === 'fallback' ? 'profile figure — no check-in weight' : 'none');
    if (!st) return t.note('No logged sets.');
    t.step('Best e1RM', wt(st.best.e1), `${setLine(st.best)} · ${fmtDate(st.best.date)}${st.best.est ? ' · backfilled' : ''}`);
    if (!raw) return t.note(`No strength standard for "${name}".`);
    const fem = S.settings.sex === 'female';
    t.step('Standard row', name, `× bw: ${raw.slice(0, 5).join(' / ')}`);
    t.step('Sex', fem ? `female, × ${raw[5]}` : 'male, × 1', fem ? 'the row\'s female factor' : '');
    const th = raw.slice(0, 5).map(v => v * (fem ? raw[5] : 1)), ratio = st.best.e1 / bw;
    t.step('Ratio', `${nice(dw(st.best.e1))} ÷ ${nice(dw(bw))} = ${ratio.toFixed(3)}× bw`);
    t.head('Tier marks');
    th.forEach((m, i) => t.step(TIERS[i], `${m.toFixed(2)}× = ${wt(m * bw)}`, ratio >= m ? 'reached' : 'not yet'));
    let score, tier = -1;
    if (ratio < th[0]) { score = ratio / th[0] * 20; t.step('Score', `${ratio.toFixed(3)} ÷ ${th[0].toFixed(2)} × 20`, 'below the first mark'); }
    else {
      let i = 4; while (i > 0 && ratio < th[i]) i--; tier = i;
      if (i === 4) { score = 100; t.step('Score', '100', 'at or past Elite'); }
      else {
        score = 20 * (i + 1) + (ratio - th[i]) / (th[i + 1] - th[i]) * 20;
        t.step('Score', `20 × ${i + 1} + (${ratio.toFixed(3)} − ${th[i].toFixed(2)}) ÷ (${th[i + 1].toFixed(2)} − ${th[i].toFixed(2)}) × 20`, '20 points a tier, the part-way bit in between');
      }
    }
    score = clamp(score, 0, 100);
    t.result('Tier', tier < 0 ? 'Untrained' : TIERS[tier]).result('Score', score.toFixed(1));
    const app = rankFor(key);
    return t.check('Score', score, app ? app.score : NaN, v => (+v).toFixed(1));
  } },

  range: { label: 'rep-range verdict', fn: (e, sets, date) => {
    const t = trace('rep-range verdict');
    const [lo, hi] = e.range || [];
    const ab = activeBlock(date || today()), tr = targetRirFor(e, ab ? ab.kind.rir : null);
    t.step('Range', `${lo}–${hi} reps`).step('Target RIR', tr, `from ${targetRirSource(e, ab ? ab.kind.rir : null)}`);
    t.step('Sets judged', date === today() ? 'today\'s' : `last time, ${fmtDate(date)}`);
    const work = (sets || []).filter(s => s.done !== false && isPRSet(s) && s.setType !== 'amrap' && s.w > 0 && s.r > 0);
    t.note('Working sets only: no warm-ups, drops or AMRAPs, and only loaded sets with reps.');
    if (!work.length) return t.note('No working sets to judge.');
    const W = Math.max(...work.map(s => s.w)), at = work.filter(s => s.w === W);
    t.step('Top weight', wt(W), `${at.length} set${at.length === 1 ? '' : 's'} at it`);
    at.forEach((s, k) => t.step(`At ${wt(W)} #${k + 1}`, `${s.r} reps${s.rpe != null ? ` @ RIR ${nice(rpeToRir(s.rpe))}` : ''}`));
    const rirs = at.filter(s => s.rpe != null).map(s => rpeToRir(s.rpe));
    const allTop = at.every(s => s.r >= hi), allRir = rirs.every(r => r >= tr);
    t.head('Rules, in order');
    t.step(`Every set reached ${hi}`, allTop ? 'yes' : 'no');
    t.step(`Every logged RIR ≥ ${tr}`, rirs.length ? (allRir ? 'yes' : 'no') : 'none logged — counts as yes');
    let kind;
    if (allTop && allRir) {
      kind = 'up';
      const step = e.leaf && (e.leaf.equipment === 'dumbbells' || e.leaf.equipment === 'kettlebell') ? 2 : 2.5;
      if (fixedStepKit(e.leaf)) { t.step('→ up', `the next ${fixedStepKit(e.leaf)} up`, 'fixed ratings: no weight is worked out'); t.result('Next', `next ${fixedStepKit(e.leaf)} × ${lo}`); }
      else {
      t.step('→ up', `max(${nice(dw(W))} × 1.025, ${nice(dw(W))} + ${step}) rounded`, 'the bigger of +2.5% or one step, rounded to what loads');
      t.result('Next', `${wt(rangeNextLoad(W, e.leaf))} × ${lo}`);
      }
    } else if (at[0].r < lo) { kind = 'below'; t.step(`First set under ${lo}`, `${at[0].r} reps`, '→ below the range'); }
    else { kind = 'build'; if (allTop) t.note(`Reached ${hi}, but harder than RIR ${tr}: same weight again.`); }
    t.result('Verdict', kind);
    const app = rangeVerdict(e, sets, date);
    return t.check('Verdict', kind, app ? app.kind : 'none');
  } },

  vbt: { label: 'bar speed', fn: v => {
    const t = trace('bar speed (VBT)');
    t.step('Phone', v.place === 'pocket' ? 'in a pocket' : 'on the bar', v.place === 'pocket' ? 'reads the body, not the bar: confidence × 0.6' : '');
    (v.reps || []).forEach((r, i) => t.step(`Rep ${i + 1}`, `${r.v.toFixed(3)} m/s`, `peak ${r.peak.toFixed(2)}${r.con ? ` · up ${r.con} s` : ''}${r.flags && r.flags.length ? ` · ${r.flags.join(', ')}` : ''}`));
    const vs = (v.reps || []).map(r => r.v);
    if (!vs.length) return t.note('No reps in the recording.');
    const best = Math.max(...vs), last = vs[vs.length - 1], loss = best > 0 ? (best - last) / best * 100 : 0;
    t.step('Best rep', `${best.toFixed(3)} m/s`, 'fastest mean concentric velocity');
    t.step('Velocity loss', `(${best.toFixed(3)} − ${last.toFixed(3)}) ÷ ${best.toFixed(3)} = ${loss.toFixed(1)}%`, '(best − last) ÷ best');
    if (v.est) {
      t.head('Reps left (Slew)');
      t.step('Method', v.est.method);
      if (vbtEst(v)) t.step('Estimate', `RIR ${nice(v.est.rir)} ± ${nice(v.est.spread)}`, `stored as RPE ${nice(v.est.rpe)}`);
      else t.note('No reps-left estimate from this set.');
      if (v.est.because) t.note(v.est.because);
      if (v.est.romCut) t.note('Range of motion shrank on the last reps, so the estimate was trimmed.');
    }
    t.step('Confidence', `${Math.round((v.conf || 0) * 100)}%`);
    t.result('Velocity loss', `${loss.toFixed(1)}%`);
    return t.check('Velocity loss', +loss.toFixed(1), v.loss, x => `${(+x).toFixed(1)}%`);
  } },

  lv: { label: "today's e1RM from bar speed", fn: e => {
    const t = trace("today's e1RM from bar speed");
    const pts = ((e.lvp && e.lvp.points) || []);
    const liftId = e.leaf ? slewLiftFor(e.leaf) : null;
    t.head('Warm-up points');
    pts.forEach((p, i) => t.step(`Point ${i + 1}`, `${wt(p.kg)} · ${p.v.toFixed(3)} m/s`, p.place === 'pocket' ? 'pocket — shown, never fitted' : ''));
    const f = lvFit(pts);
    if (!f) return t.note('Needs 3+ bar points spread over at least 15% of the heaviest, with speed dropping as the weight rises.');
    f.out.forEach(p => t.step('Left out', `${wt(p.kg)} · ${p.v.toFixed(3)}`, `faster than a lighter point by over ${LV_SLACK} m/s`));
    t.head('The line');
    t.step('Fit', `v = ${f.a.toFixed(4)} ${f.b < 0 ? '−' : '+'} ${Math.abs(f.b).toFixed(6)} × kg`, `least squares on ${f.n} points`);
    t.step('Scatter', `${f.rse.toFixed(4)} m/s`, 'residual standard error');
    const s = (S.settings.slewProfiles || {})[liftId] || {}, prior = Slew.defaultProfile(liftId).v0;
    const obs = (s.v0Obs || []).map(o => o.v).filter(x => x > 0), mvt = mvtFor(liftId);
    t.head('Speed at a max (MVT)');
    t.step('Population prior', `${prior.toFixed(3)} m/s`, `for ${liftId}`);
    t.step('Your failed reps', obs.length ? obs.map(x => x.toFixed(2)).join(', ') : 'none yet');
    if (obs.length) t.step('Shrunk', `(${MVT_PRIOR_WEIGHT} × ${prior.toFixed(3)} + ${obs.reduce((a, b) => a + b, 0).toFixed(3)}) ÷ (${MVT_PRIOR_WEIGHT} + ${obs.length})`, 'the prior counts as 3 observations');
    t.step('MVT used', `${mvt.toFixed(3)} m/s`);
    const mid = (mvt - f.a) / f.b, pct = f.heavy / mid * 100;
    t.head('Where they meet');
    t.step('e1RM', `(${mvt.toFixed(3)} − ${f.a.toFixed(4)}) ÷ ${f.b.toFixed(6)} = ${wt(mid)}`);
    t.step('Heaviest warm-up', `${wt(f.heavy)} = ${pct.toFixed(0)}%`, mid > f.heavy ? '' : 'already at or past the e1RM: not believable');
    if (!(mid > f.heavy) || pct < 35) return t.note(pct < 35 ? 'Under 35%: too far to extrapolate.' : 'No range shown.');
    const half = 4 + (f.rse / Math.abs(f.b)) / mid * 100 + Math.max(0, 80 - pct) * 0.5;
    t.step('± width', `4 + scatter ${((f.rse / Math.abs(f.b)) / mid * 100).toFixed(1)} + far-out ${(Math.max(0, 80 - pct) * 0.5).toFixed(1)} = ${half.toFixed(1)}%`, 'base 4%, the line\'s scatter in kg as a %, and half a point per % the heaviest warm-up sits under 80%');
    t.result('Range', `${nice(dw(mid * (1 - half / 100), 0))}–${nice(dw(mid * (1 + half / 100), 0))} ${U()}`);
    const app = lvDay(e);
    return t.check('Middle', mid, app ? app.mid : NaN, x => wt(x));
  } },

  rec: { label: 'recovery', fn: key => {
    const t = trace(`${MUSCLES[key] || key} — recovery`);
    const now = Date.now(), since = now - RECOVERY.days * 864e5, tau = muscleTau(key);
    t.step('Window', `last ${RECOVERY.days} days`).step('Half-life style decay', `e^(−hours ÷ ${tau})`, BIG_MUSCLES.includes(key) ? 'big muscle: 36 h' : 'smaller muscle: 24 h');
    t.note('Each set counts by effort: RIR ≤ 1 = 1, 2 = 0.85, 3 = 0.7, more = 0.55, unlogged = 0.8; drop sets × 0.6; warm-ups 0.');
    const list = S.workouts.filter(w => w.status === 'completed' && w.kind !== 'cardio' && woTime(w) >= since && woTime(w) <= now);
    if (S.active && S.active.kind !== 'cardio' && S.active.exercises) list.push({ ...S.active, end: now, live: true });
    let sum = 0;
    t.head('What trained it');
    list.forEach(wo => {
      const hrs = Math.max(0, (now - woTime(wo)) / 36e5);
      (wo.exercises || []).forEach(e => {
        const lm = e.leaf ? leafMuscles(e.leaf) : (exInfo(exName(e)) ? { m: exMuscles(exName(e)) } : null);
        const share = lm && lm.m && lm.m[key];
        if (!share) return;
        const ss = e.sets.filter(s => (wo.live ? s.done : s.done !== false) && (s.r > 0 || s.sec > 0 || s.m > 0));
        const eff = ss.reduce((a, s) => a + setEffort(s), 0);
        if (!eff) return;
        const f = eff * share * Math.exp(-hrs / tau);
        sum += f;
        t.step(`${exFull(e)} · ${wo.live ? 'today' : fmtDate(wo.date)}`, f.toFixed(2), `${ss.length} sets → effort ${eff.toFixed(2)} × share ${share} × e^(−${hrs.toFixed(0)} ÷ ${tau})`);
      });
    });
    const level = RECOVERY.levels.filter(x => sum >= x).length;
    t.step('Total', sum.toFixed(2), 'about this many hard sets are still in the muscle');
    t.step('Bands', RECOVERY.levels.join(' / '), RECOVERY_WORDS.join(' · '));
    t.result('Reads as', RECOVERY_WORDS[level]);
    if (sum > RECOVERY.fresh) t.result('Fresh in', `~${Math.ceil(tau * Math.log(sum / RECOVERY.fresh))} h`, `${tau} × ln(${sum.toFixed(2)} ÷ ${RECOVERY.fresh})`);
    const app = fatigueMap(now)[key];
    return t.check('Total', sum, app ? app.f : 0, x => (+x).toFixed(2));
  } },

  dots: { label: 'DOTS and IPF GL points', fn: (total, bw, sex, bench) => {
    const t = trace('DOTS and IPF GL');
    const fem = sex === 'female';
    t.step('Total', wt(total)).step('Bodyweight', wt(bw)).step('Sex', fem ? 'female' : 'male', 'picks the coefficients');
    const c = fem ? [-57.96288, 13.6175032, -0.1126655495, 0.0005158568, -0.0000010706]
      : [-307.75076, 24.0900756, -0.1918759221, 0.0007391293, -0.000001093];
    const x = clamp(bw, 40, 210);
    t.head('DOTS');
    if (x !== bw) t.step('Bodyweight used', `${nice(x)} kg`, 'DOTS clamps to 40–210 kg');
    const den = c[0] + c[1] * x + c[2] * x ** 2 + c[3] * x ** 3 + c[4] * x ** 4;
    t.step('Denominator', den.toFixed(4), `a + b·bw + c·bw² + d·bw³ + e·bw⁴ with ${c.join(', ')}`);
    const D = den > 0 ? total * 500 / den : 0;
    t.result('DOTS', `${nice(dw(total, 2))} × 500 ÷ ${den.toFixed(4)} = ${nice(D)}`);
    t.head(`IPF GL (${bench ? 'bench only' : 'classic'})`);
    const k = bench ? (fem ? [142.40398, 442.52671, 0.04724] : [320.98041, 281.40258, 0.01008])
      : (fem ? [610.32796, 1045.59282, 0.03048] : [1199.72839, 1025.18162, 0.00921]);
    const gd = k[0] - k[1] * Math.exp(-k[2] * bw), G = gd > 0 ? total * 100 / gd : 0;
    t.step('Denominator', `${k[0]} − ${k[1]} × e^(−${k[2]} × ${nice(bw)}) = ${gd.toFixed(4)}`);
    t.result('IPF GL', `${nice(total)} × 100 ÷ ${gd.toFixed(4)} = ${nice(G)}`);
    return t.check('DOTS', D, dots(total, bw, sex), nice).check('IPF GL', G, glPoints(total, bw, sex, bench), nice);
  } },

  cal: { label: 'body fat from calipers', fn: id => {
    const c = (S.calipers || []).find(x => x.id === id), M = c && CAL_METHODS[c.method];
    if (!M) return null;
    const t = trace(`body fat — ${M.short}`);
    t.step('Method', M.name).step('Sex', c.sex || 'male').step('Age', c.age || 0, 'on the day');
    t.head('Skinfolds (mm)');
    const sites = M.sites(c.sex);
    const means = sites.map(s => {
      const r = ((c.mm || {})[s] || []).filter(x => x > 0), m = r.length ? mean(r) : null;
      t.step(s, m == null ? 'missing' : nice(m), r.length > 1 ? `mean of ${r.join(', ')}` : '');
      return m;
    });
    if (means.some(x => x == null)) return t.note('A site is missing, so there is no result.');
    const sum = means.reduce((a, b) => a + b, 0), bd = M.bd(sum, c.age || 0, c.sex);
    t.step('Sum', `${nice(sum)} mm`);
    const eq = {
      jp3: c.sex === 'female' ? '1.0994921 − 0.0009929·S + 0.0000023·S² − 0.0001392·age' : '1.10938 − 0.0008267·S + 0.0000016·S² − 0.0002574·age',
      jp7: c.sex === 'female' ? '1.097 − 0.00046971·S + 0.00000056·S² − 0.00012828·age' : '1.112 − 0.00043499·S + 0.00000055·S² − 0.00028826·age',
      dw4: (() => { const b = DW_BANDS[c.sex === 'female' ? 'female' : 'male'].filter(x => (c.age || 0) >= x[0]).pop() || DW_BANDS.male[0]; return `${b[1]} − ${b[2]}·log10(S) (age ${b[0]}+ band)`; })(),
    }[c.method];
    t.step('Body density', bd.toFixed(5), eq);
    const bf = 495 / bd - 450;
    t.step('Siri', `495 ÷ ${bd.toFixed(5)} − 450`);
    t.result('Body fat', `${bf.toFixed(1)}%`, bf >= 3 && bf <= 50 ? '' : 'outside 3–50% — check the readings');
    const wk = weightNear(c.date);
    if (wk) t.step('Weigh-in within 3 days', wt(wk)).step('Fat / lean', `${wt(wk * bf / 100)} / ${wt(wk * (1 - bf / 100))}`);
    else t.note('No weigh-in within 3 days, so no fat and lean mass.');
    const app = caliperCalc(c);
    return t.check('Body fat', bf, app ? app.bf : NaN, x => `${(+x).toFixed(1)}%`);
  } },

  mob: { label: 'mobility test', fn: id => {
    const T = mobTestDef(id);
    if (!T) return null;
    const t = trace(T.label);
    t.step('Better', T.better > 0 ? 'higher' : 'lower').step('Unit', T.scale ? `steps: ${T.scale.join(' → ')}` : T.unit || '—');
    t.note(`Several tries on a day count as that day's best${T.balance ? '; balance tries under 1 s are never saved' : ''}.`);
    const sides = T.sides ? ['L', 'R'] : [null];
    sides.forEach(sd => {
      const sr = mobTestSeries(id, sd), raw = (S.mobTests || []).filter(x => x.test === id && (x.side || null) === sd);
      const last = sr[sr.length - 1];
      t.head(sd ? (sd === 'L' ? 'Left' : 'Right') : 'Result');
      t.step('Tries saved', raw.length).step('Days', sr.length);
      if (last) {
        const day = raw.filter(x => x.date === last.date).map(x => x.v);
        t.step('Latest day', fmtDate(last.date), day.length > 1 ? `tries ${day.map(x => mobTestText(T, x)).join(', ')}` : '');
        t.result('Best that day', mobTestText(T, last.v));
      }
    });
    const g = mobTestGap(id);
    if (T.sides && !T.scale) {
      t.head('Left against right');
      if (!g) t.note('Needs a day with both sides tested.');
      else if (g.even) t.result('Gap', 'even', fmtDate(g.date));
      else {
        const L = mobTestSeries(id, 'L').find(p => p.date === g.date).v, R = mobTestSeries(id, 'R').find(p => p.date === g.date).v;
        const gap = Math.abs(L - R) / Math.max(L, R) * 100;
        t.step('Same day', `${fmtDate(g.date)}: L ${nice(L)} · R ${nice(R)}`);
        t.result('Gap', `|${nice(L)} − ${nice(R)}| ÷ ${nice(Math.max(L, R))} = ${gap.toFixed(0)}%`, `${g.weak === 'L' ? 'left' : 'right'} behind`);
        t.check('Gap', gap, g.gap, x => `${(+x).toFixed(0)}%`);
      }
    }
    return t;
  } },

  fit: { label: 'fitting test score', fn: (id, item) => {
    const t = (S.fitTests || []).find(x => x.id === id) || (S.fitDraft && S.fitDraft.id === id ? S.fitDraft : null);
    if (!t) return null;
    const isP = !!FIT.patterns[item], T = trace(`${isP ? FIT.patterns[item].label : FIT.others[item].label} — fitting test`);
    const r = isP ? fitStrength(t, item, T) : fitOther(t, item, T);
    if (!r) return T.note('Not tested.');
    T.result('Score', `${r.score} of 5 — ${r.rating}`);
    if (!isP && r.flag) T.result('Flag', FIT.others[item].action, `score ${FIT.flagAt} or lower`);
    const app = fitResults(t)[isP ? 'strength' : 'others'].find(x => x.id === item);
    return T.check('Score', r.score, app ? app.score : NaN);
  } },

  digest: { label: 'what the coach read', fn: () => {
    const D = coachDigest(), t = trace('what the coach read');
    t.step('Last 7 days', `${D.week.done} sessions`, `${D.week.missed} planned missed · ${D.week.prev} the week before`);
    D.lifts.forEach(l => t.step(l.name, l.now ? `e1RM ${wt(l.now)}` : '—', `${l.then ? `2 weeks ago ${wt(l.then)}` : 'no 2-week figure'}${l.stall ? ' · stalled' : ''} — historyE1, last 3 sessions weighted 3:2:1`));
    t.step('Typed RIR − target', D.rirGap != null ? nice(D.rirGap) : '—', `${D.rirN} sets with a target in 14 days (needs 4)`);
    t.step('Typed RIR − bar speed', D.vbtGap != null ? nice(D.vbtGap) : '—');
    t.head('Sets per muscle this week');
    Object.entries(D.muscles).sort((a, b) => b[1] - a[1]).forEach(([k, v]) => t.step(MUSCLES[k] || k, nice(v), v < CO_LOW_SETS ? 'low' : v > CO_HIGH_SETS ? 'high' : ''));
    t.head('Check-ins');
    t.step('This week', `sleep ${D.ci.sleep ? nice(D.ci.sleep) : '—'} · energy ${D.ci.energy ? nice(D.ci.energy) : '—'} · soreness ${D.ci.soreness ? nice(D.ci.soreness) : '—'}`, `${D.ci.n} check-ins`);
    t.step('Last week', `sleep ${D.ciPrev.sleep ? nice(D.ciPrev.sleep) : '—'} · energy ${D.ciPrev.energy ? nice(D.ciPrev.energy) : '—'}`);
    t.step('Weeks in a row trained', D.streak);
    const dl = coDeloadScore(D);
    t.step('Deload score', dl.score, dl.pts.map(p => `${p[1]} (+${p[0]})`).join('; ') || 'nothing');
    return t;
  } },

  cardio: { label: 'heart-rate cue', fn: () => {
    const L = cardioWhyLast;
    const t = trace('heart-rate cue');
    if (!L) return t.note('No check has run yet — start the session with debug mode on.');
    const cfg = cardioNorm(L.cfg), M = cardioMachine(cfg.machine), P = cardioPrimary(M), st = L.st;
    const since = x => x == null ? Infinity : st.el - x, sec = x => x === Infinity ? 'never' : `${Math.round(x)} s`;
    t.step('At', `${Math.round(st.el)} s in`, M.label || cfg.machine);
    t.step('HR, last 5 s', st.hr5 == null ? 'none' : Math.round(st.hr5)).step('HR, last 20 s', st.hr20 == null ? 'none' : Math.round(st.hr20), 'the smoothed figure the zone uses');
    t.step('Zone', cardioHasZone(cfg) ? `${cfg.lo}–${cfg.hi}, aiming at ${(cfg.lo + cfg.hi) / 2}` : 'none').step('Ceiling', cfg.ceiling > 0 ? cfg.ceiling : 'off');
    t.head('Rules, first match wins');
    let rule = null;
    const go = (name, hit, note) => { if (rule) return; t.step(name, hit ? 'yes — stops here' : 'no', note); if (hit) rule = name; };
    go('1. Over the ceiling', st.hr5 != null && cfg.ceiling > 0 && st.hr5 > cfg.ceiling && since(st.lastCeil) >= CARDIO.ceilGap, `5-s HR over the ceiling, and ${CARDIO.ceilGap} s since the last ceiling cue (${sec(since(st.lastCeil))})`);
    const plan = warmPlan(cfg);
    go('2. Warm-up', !!(plan && !st.warmDone), plan ? `${plan.n} steps, one every ${Math.round(plan.every)} s; hands over early once 20-s HR reaches ${cfg.lo}` : 'no warm-up set');
    go('3. No zone', !cardioHasZone(cfg), 'just a log');
    go('4. Settling', !plan && st.el < CARDIO.settle, `first ${CARDIO.settle} s with no warm-up`);
    go('5. Interval', since(st.lastCheck) < cfg.interval, `${sec(since(st.lastCheck))} since the last check, every ${cfg.interval} s`);
    go('6. Waiting for HR to answer', since(st.lastChange) < CARDIO.respond, `${sec(since(st.lastChange))} since the last change, waits ${CARDIO.respond} s`);
    go('7. No fresh HR', st.hr20 == null, 'silent');
    if (!rule) {
      const miss = st.hr20 - (cfg.lo + cfg.hi) / 2, K = M.knobs[cfg.cue];
      t.step('Miss', `${Math.round(st.hr20)} − ${(cfg.lo + cfg.hi) / 2} = ${nice(miss)} bpm`, `within ±${CARDIO.tol} counts as on target`);
      if (Math.abs(miss) <= CARDIO.tol) {
        rule = 'On target';
        if (cfg.trend) {
          if (st.slope == null) t.step('Trend coach', 'no slope yet', `needs ${45} s of samples`);
          else {
            const proj = st.hr20 + st.slope * CARDIO.trendAhead / 60;
            t.step('Trend coach', `${st.slope >= 0 ? '+' : ''}${nice(st.slope)} bpm/min → ${Math.round(proj)} in ${CARDIO.trendAhead} s`,
              `least squares over the last ${CARDIO.trendWin} s; acts when the slope is ${CARDIO.trendMin}+ bpm/min and the projection leaves ${cfg.lo}–${cfg.hi}`);
            if (Math.abs(st.slope) >= CARDIO.trendMin && (proj > cfg.hi || proj < cfg.lo)) rule = proj > cfg.hi ? 'Trend easier' : 'Trend harder';
          }
        }
      } else {
        const r1 = x => Math.round(x * 1000) / 1000, dir = miss < 0 ? 1 : -1;
        const step = clamp(r1(Math.round(Math.abs(miss) * K.perBpm / K.round) * K.round), K.step[0], K.step[1]);
        t.step('Step', `${nice(Math.abs(miss))} × ${K.perBpm} per bpm, rounded to ${K.round}, kept in ${K.step[0]}–${K.step[1]} = ${step}`, K.label);
        const target = r1(clamp(st.v[cfg.cue] + K.harder * dir * step, ...K.bounds));
        t.step('New value', `${knobVal(K, st.v[cfg.cue])} → ${knobVal(K, target)}`, `kept inside ${K.bounds.join('–')}`);
        rule = dir > 0 ? 'Harder' : 'Easier';
      }
    }
    t.result('Outcome', rule);
    const d = L.d;
    t.step('Cue the app gave', d && d.cue ? d.cue.text || d.cue.kind : 'no cue');
    /* cardioDecide is pure, so replaying the same inputs is the check. */
    const kind = { '1. Over the ceiling': 'ceiling', Harder: 'up', Easier: 'down', 'Trend harder': 'up', 'Trend easier': 'down' }[rule] || 'none';
    if (rule !== '2. Warm-up') {
      const r = cardioDecide(L.cfg, st);
      t.check('Outcome', kind, r && r.cue ? r.cue.kind : 'none');
    }
    return t;
  } },
});

const PROFILE_FIELDS = ['handle', 'sex', 'dob', 'heightCm', 'bodyweight', 'activity', 'nutritionGoal'];

export function openProfile(snap) {
  const st = S.settings;
  /* The derived figures (BMR, DOTS, category) read S.settings, so editing has to
     write there to recompute live. That would make Cancel a lie, so the values
     as they were on opening are carried through each redraw and put back if you
     cancel. */
  const original = snap || Object.fromEntries(PROFILE_FIELDS.map(k => [k, st[k]]));
  const draw = () => {
    const age = ageFrom(st.dob);
    const cat = ageCategory(age);
    const bw = bodyweightSource();
    const t = suggestedTargets();
    const ps = priorityStats();
    const missing = [
      !bw.kg && 'bodyweight',
      !st.heightCm && 'height',
      age == null && 'date of birth',
    ].filter(Boolean);
    return `
      <div class="field"><label>Name on shared images</label>
        <input id="pfHandle" value="${esc(st.handle || '')}" placeholder="@yourname — leave blank for none"></div>

      <div class="row" style="gap:8px">
        <div class="grow"><label for="pfSex">Sex</label>
          <select id="pfSex">
            <option value="male"${st.sex === 'male' ? ' selected' : ''}>Male</option>
            <option value="female"${st.sex === 'female' ? ' selected' : ''}>Female</option>
          </select>
          <div class="sub" style="margin-top:4px">Sets the DOTS coefficient.</div>
        </div>
        <div class="grow"><label for="pfDob">Date of birth</label>
          <input type="date" id="pfDob" value="${esc(st.dob || '')}" max="${today()}">
          <div class="sub" style="margin-top:4px">${age == null ? 'For your age category.' : `${age} · ${cat || 'no category'} (IPF)`}</div>
        </div>
      </div>

      <div class="row" style="gap:8px">
        <div class="grow"><label for="pfHeight">Height (cm)</label>
          <input type="number" inputmode="numeric" id="pfHeight" value="${st.heightCm || ''}" placeholder="—"></div>
        <div class="grow"><label for="pfBw">Bodyweight (${U()})</label>
          <input type="number" step="0.1" inputmode="decimal" id="pfBw" value="${st.bodyweight ? dw(st.bodyweight) : ''}" placeholder="—">
        </div>
      </div>
      <div class="sub" style="margin-top:-4px;margin-bottom:10px">${bw.from === 'checkin'
      ? `Using <b>${wt(bw.kg)}</b> from your check-in on ${fmtDate(bw.date)}. The box above is the fallback for when you have not checked in.`
      : bw.from === 'fallback'
        ? `No check-in yet, so <b>${wt(bw.kg)}</b> is being used. Log a check-in and that takes over.`
        : 'No bodyweight yet — DOTS and calorie estimates need one.'}</div>

      <div class="hr"></div>
      <div class="eyebrow" style="margin-bottom:6px">Lifting</div>
      <div class="stats grid3" style="margin-bottom:4px">
        <div class="stat"><div class="k">Tested total</div><div class="v">${ps.total ? wt(ps.total, 0) : '—'}</div></div>
        <div class="stat"><div class="k">DOTS</div><div class="v" style="color:var(--purple)">${ps.dots ? Math.round(ps.dots) : '—'}</div></div>
        <div class="stat"><div class="k">Category</div><div class="v" style="font-size:15px">${cat || '—'}</div></div>
      </div>
      ${ps.untested ? `<div class="sub">${ps.untested === ps.lifts.length
      ? 'None of your three lifts has a tested single yet, so there is no total.'
      : `${ps.untested} of your three lifts ${ps.untested === 1 ? 'is' : 'are'} untested, so there is no total yet.`}</div>` : ''}

      <div class="hr"></div>
      <div class="eyebrow" style="margin-bottom:6px">Daily energy</div>
      <div class="row" style="gap:8px">
        <div class="grow"><label for="pfAct">Activity</label>
          <select id="pfAct">${Object.entries(ACTIVITY).map(([k, a]) =>
        `<option value="${k}"${st.activity === k ? ' selected' : ''}>${a.label} — ${a.note}</option>`).join('')}</select></div>
      </div>
      <div class="field"><label>Goal</label>
        <div class="seg" id="pfGoalSeg">${Object.entries(NUTRITION_GOAL).map(([k, g]) =>
          `<button data-g="${k}" class="${(st.nutritionGoal || 'maintain') === k ? 'on' : ''}">${g.label}</button>`).join('')}</div>
      </div>
      ${t ? `
        <div class="stats grid3" style="margin-bottom:8px">
          <div class="stat"><div class="k">BMR</div><div class="v">${t.bmr}<small>kcal</small></div></div>
          <div class="stat"><div class="k">Maintenance</div><div class="v">${t.tdee}<small>kcal</small></div></div>
          <div class="stat"><div class="k">Target</div><div class="v" style="color:var(--gold)">${t.kcal}<small>kcal</small></div></div>
        </div>
        <div class="sub" style="margin-bottom:9px">${t.p} g protein · ${t.c} g carbs · ${t.f} g fat — protein at 2 g and fat at 0.8 g per kilo, carbohydrate taking the rest. An estimate; correct it against the scale over a fortnight.</div>`
      : `<div class="sub">Add ${missing.join(', ')} and this works out your maintenance calories and a macro split.</div>`}
    `;
  };

  modal({
    title: 'Profile',
    body: draw(),
    foot: `<button class="btn ghost" id="pfCancel">Cancel</button><button class="btn primary" id="pfSave">Save</button>`,
    onOpen(bg) {
      const collect = () => {
        st.handle = $('#pfHandle', bg).value.trim().slice(0, 32);
        st.sex = $('#pfSex', bg).value;
        st.dob = $('#pfDob', bg).value || '';
        st.heightCm = Math.max(0, Math.min(260, +$('#pfHeight', bg).value || 0));
        const raw = $('#pfBw', bg).value;
        st.bodyweight = raw === '' ? 0 : toKg(+raw);
        st.activity = $('#pfAct', bg).value;
      };
      const re = () => { collect(); closeModal(); openProfile(original); };

      ['#pfSex', '#pfDob', '#pfHeight', '#pfBw', '#pfAct'].forEach(sel => {
        const el = $(sel, bg);
        if (el) el.onchange = re;
      });
      bg.querySelectorAll('#pfGoalSeg [data-g]').forEach(b => b.onclick = () => {
        st.nutritionGoal = b.dataset.g; re();
      });
      $('#pfCancel', bg).onclick = () => { Object.assign(st, original); closeModal(); render(); };
      $('#pfSave', bg).onclick = () => { collect(); save(); closeModal(); render(); toast('Profile saved', 'green'); };
    },
  });
}

export function openSettings() {
  modal({
    title: 'Settings',
    body: `
      <nav class="row wrap" id="stJump" aria-label="Jump to a section of Settings" style="gap:6px;margin-bottom:14px">
        ${[['stSecLook', 'Look & units'], ['stSecTimers', 'Timers'], ['stSecKit', 'Places & kit'], ['stSecAi', 'AI & extras'], ['stSecProgram', 'Program'], ['stSecVideo', 'Video'], ['stSecData', 'Data & backup']]
          .map(([id, label]) => `<button class="chip" data-stjump="${id}" style="cursor:pointer">${label}</button>`).join('')}
      </nav>
      <div class="field" id="stSecLook"><label>Skin</label>
        <div class="seg" id="skinSeg">
          <button data-sk="ironlog" class="${S.settings.skin !== 'win98' ? 'on' : ''}">Ironlog</button>
          <button data-sk="win98" class="${S.settings.skin === 'win98' ? 'on' : ''}">Windows 98</button>
        </div>
        <div class="sub" style="margin-top:4px">Applies straight away — it is only the paint. Every number, PR and session is the same underneath.</div>
      </div>
      <div class="field"><label>Units</label>
        <div class="seg" id="unitSeg">
          <button data-u="kg" class="${U() === 'kg' ? 'on' : ''}">Kilograms</button>
          <button data-u="lb" class="${U() === 'lb' ? 'on' : ''}">Pounds</button>
        </div></div>
      <div class="grid2">
        <div class="field" id="stSecTimers"><label>Timer sound</label>
          <div class="seg" id="sndSeg">
            <button data-v="1" class="${S.settings.sound !== false ? 'on' : ''}">On</button>
            <button data-v="0" class="${S.settings.sound === false ? 'on' : ''}">Off</button>
          </div></div>
        <div class="field"><label>Vibration</label>
          <div class="seg" id="vibSeg">
            <button data-v="1" class="${S.settings.vibrate !== false ? 'on' : ''}">On</button>
            <button data-v="0" class="${S.settings.vibrate === false ? 'on' : ''}">Off</button>
          </div></div>
      </div>
      <div class="sub" style="margin:-4px 0 10px">Beeps and buzzes from the hold and rest timers. A phone on silent may still mute the beeps — the browser can't tell.</div>
      <div class="field"><label>Rest timer</label>
        <div class="seg" id="restAutoSeg">
          <button data-v="1" class="${S.settings.restAuto !== false ? 'on' : ''}">Start on tick</button>
          <button data-v="0" class="${S.settings.restAuto === false ? 'on' : ''}">Off</button>
        </div></div>
      <div class="grid3">
        <div class="field"><label>Main lifts</label>
          <input type="text" inputmode="numeric" id="stRestMain" value="${fmtSec(S.settings.restDefault || 180)}"></div>
        <div class="field"><label>Accessories</label>
          <input type="text" inputmode="numeric" id="stRestAcc" value="${fmtSec(S.settings.restAccessory || 90)}"></div>
        <div class="field"><label>Warn (s before)</label>
          <input type="number" inputmode="numeric" id="stRestWarn" value="${+S.settings.restWarn || 0}" min="0" max="60"></div>
      </div>
      <div class="sub" style="margin:-4px 0 10px">Main lifts are your priority lifts and heavy barbell compounds. Warm-ups rest half as long. Any exercise can have its own rest from its ⋯ menu; ±15 s during a session sticks for that session.</div>
      ${'Notification' in window ? `<button class="btn sm wide ghost" id="stRestNote" style="margin-bottom:6px" ${Notification.permission !== 'default' ? 'disabled' : ''}>${
        Notification.permission === 'granted' ? 'Rest notifications on' : Notification.permission === 'denied' ? 'Notifications blocked in browser settings' : 'Notify me when rest ends in the background'}</button>
      <div class="sub" style="margin-bottom:10px">Best effort — a phone may pause the app in the background before the rest is up.</div>` : ''}
      <div class="field"><label>Profile</label>
        <button class="btn sm wide ghost" id="stProfile">Sex, bodyweight, age and targets →</button>
        <div class="sub" style="margin-top:4px">Sex and bodyweight set your DOTS; they live in the profile now rather than here.</div>
      </div>
      <div class="hr"></div>
      <div class="eyebrow" id="stSecKit" style="margin-bottom:6px">Places</div>
      <div class="sub" style="margin-bottom:8px">${places().length ? `${places().map(x => esc(x.name)).join(' · ')} — the kit at each, so exercises you can't do there are greyed.` : 'Name where you train and the kit there — Home, Gym, a hotel — and exercises you can\'t do there are greyed.'}</div>
      <button class="btn sm wide ghost" id="stPlaces" style="margin-bottom:4px">${places().length ? 'Manage places →' : 'Set up places →'}</button>
      <div class="hr"></div>
      <div class="eyebrow" style="margin-bottom:6px">Bars${places().length ? ' — main inventory' : ''}</div>
      <div class="sub" style="margin-bottom:8px">"For" picks the bar automatically on lifts with that equipment, so a trap-bar deadlift loads from the trap bar.</div>
      <div id="stBars">${mainBars().map((b, i) => barRow(i, b)).join('')}</div>
      <div class="row wrap" style="gap:6px">
        <button class="btn xs ghost" id="stAddBar">+ Add bar</button>
        ${BAR_PRESETS.filter(p => p.name !== 'Barbell').map((p, i) => `<button class="btn xs ghost" data-bpre="${i + 1}">+ ${esc(p.name)}</button>`).join('')}
      </div>

      <div class="hr"></div>
      <div class="eyebrow" style="margin-bottom:6px">Plates — pairs you own</div>
      <div class="sub" style="margin-bottom:8px">Counted in pairs, so a stack the calculator gives you is one you can actually build.</div>
      <div id="stPlates">${mainPlates().map((p, i) => `
        <div class="row" style="gap:8px;margin-bottom:6px;align-items:center">
          <input type="number" step="0.25" inputmode="decimal" data-pk="${i}" value="${dw(p.kg, 2)}" style="width:82px" aria-label="Plate size (${U()})">
          <span class="sub">${U()} ×</span>
          <input type="number" inputmode="numeric" data-pp="${i}" value="${p.pairs}" style="width:64px" aria-label="Pairs of ${dw(p.kg, 2)} ${U()} plates">
          <span class="sub grow">pairs</span>
          <button class="btn sm ghost" data-prm="${i}" aria-label="Remove the ${dw(p.kg, 2)} ${U()} plates">−</button>
        </div>`).join('')}</div>
      <button class="btn xs ghost" id="stAddPlate">+ Add plate</button>
      <div class="field" style="margin-top:10px"><label for="stCollar">Collars — each (${U()})</label>
        <input type="number" step="0.25" inputmode="decimal" id="stCollar" value="${S.settings.collarKg > 0 ? dw(S.settings.collarKg, 2) : ''}" placeholder="0 — spring clips" style="width:140px">
        <div class="sub" style="margin-top:4px">Competition collars are 2.5 kg each. Counted as part of the bar when working out plates.</div></div>

      <div class="hr"></div>
      <div class="field"><label>Gym → platform estimate (%)</label>
        <input type="number" step="1" inputmode="numeric" id="stPlatform" value="${platformPct()}" placeholder="96">
        <div class="sub" style="margin-top:4px">Used for placing predictions. Openers are conservative, thirds get missed, nerves cost kilos — 96% is a reasonable default.</div>
      </div>
      <div class="hr"></div>
      <div class="eyebrow" id="stSecAi" style="margin-bottom:6px">AI — on your own key</div>
      <div class="sub" style="margin-bottom:8px">Optional. Ironlog has no AI server: with your own Anthropic key, the phone calls Anthropic directly and you pay them for what you use — fractions of a penny a time. Everything works without it.</div>
      <div class="field"><label for="stKey">Anthropic API key</label>
        <div class="row" style="gap:6px"><input id="stKey" type="password" autocomplete="off" spellcheck="false" style="flex:1"
          value="${esc(aiKey())}" placeholder="sk-ant-…"><button class="btn sm ghost" id="stKeyShow" aria-pressed="false">Show</button></div>
        <div class="sub" style="margin-top:4px">Kept on this phone only and sent nowhere but Anthropic. Clearing site data removes it. Get one at console.anthropic.com.</div>
        <div class="row" style="gap:8px;margin-top:6px;align-items:center"><button class="btn sm" id="stKeyTest">Check key</button><span class="sub" id="stKeyMsg" role="status"></span></div>
      </div>
      <div class="field"><label for="stAiCap">Monthly cap ($)</label>
        <input id="stAiCap" type="number" inputmode="decimal" step="0.5" min="0" value="${aiCap()}">
        <div class="sub" style="margin-top:4px">AI stops for the rest of the month once this phone's estimated spend reaches it. 0 turns AI off. An estimate from token counts — Anthropic's console is the real bill.</div>
      </div>
      <div id="stAiUse">${aiUsageHtml()}</div>
      <div class="field"><label>Debug mode — show the working</label>
        <div class="seg" id="dbgSeg">
          <button data-v="1" class="${debugOn() ? 'on' : ''}">On</button>
          <button data-v="0" class="${debugOn() ? '' : 'on'}">Off</button>
        </div>
        <div class="sub" style="margin-top:4px">Puts a small <b>how?</b> beside worked-out numbers — e1RM, PRs, tiers, points, recovery, body fat, VBT, cardio cues, test scores. It shows the inputs, the sum and the result, and you can copy it into a bug report. Changes nothing.</div>
      </div>
      <div class="field"><label>Count backfilled sessions toward PRs</label>
        <div class="seg" id="prEstSeg">
          <button data-pe="1" class="${S.settings.prCountEst !== false ? 'on' : ''}">Yes</button>
          <button data-pe="0" class="${S.settings.prCountEst === false ? 'on' : ''}">No</button>
        </div>
        <div class="sub" style="margin-top:4px">Backfilled sets show EST against a best. Say No only if your backfill was the plan's prescription rather than what you actually lifted.</div>
      </div>
      <div class="hr"></div>
      <div class="field"><label>Opener % of latest tested single</label>
        <input type="number" step="1" inputmode="numeric" id="stOpener" value="${openerPct()}" placeholder="90">
        <div class="sub" style="margin-top:4px">90% is the usual default. For a debut, 87–88% is a weight you could triple cold — a missed opener costs the whole session.</div>
      </div>
      ${PROGRAM_MANIFEST ? `
      <div class="hr"></div>
      <div class="eyebrow" id="stSecProgram" style="margin-bottom:8px">Training program</div>
      <div class="row between" style="margin-bottom:10px">
        <div class="grow"><div style="font-weight:650;font-size:13.5px">${esc(PROGRAM_MANIFEST.name)}</div>
          <div class="sub">${programInstalled(PROGRAM_MANIFEST.id)
        ? `${S.workouts.filter(w => w.prog === PROGRAM_MANIFEST.id && w.status === 'planned').length} planned sessions installed`
        : `${PROGRAM_MANIFEST.sessions} sessions · not installed`}</div></div>
        <button class="btn sm" id="stProgram">${programInstalled(PROGRAM_MANIFEST.id) ? 'Manage' : 'Install'}</button>
      </div>` : ''}
      ${oldPrograms().map(id => `
      <div class="row between" style="margin-bottom:10px">
        <div class="grow"><div style="font-weight:650;font-size:13.5px">${esc(programName(id))}</div>
          <div class="sub">Earlier program · ${S.workouts.filter(w => w.prog === id && w.status === 'planned').length} planned sessions left</div></div>
        <button class="btn sm danger" data-oldprog="${esc(id)}" aria-label="Remove planned sessions from ${esc(programName(id))}">Remove</button>
      </div>`).join('')}
      <button class="btn sm wide" id="stPlanImport" style="margin-top:4px">Bring in a plan…</button>
      <div class="hr"></div>
      <div class="eyebrow" style="margin-bottom:8px">Backfill</div>
      <div class="sub" style="margin-bottom:8px">Mark past planned sessions as done at their prescribed loads. Today is never included. Flagged as estimates — they count toward volume and streaks but can't set a PR.</div>
      <div class="row" style="gap:8px;align-items:center">
        <select id="stBfDays" class="grow" aria-label="Mark planned sessions done from">
          <option value="7">Last 7 days</option>
          <option value="14" selected>Last 14 days</option>
          <option value="28">Last 28 days</option>
        </select>
        <button class="btn sm" id="stBackfill">Mark done</button>
      </div>
      <div class="sub" id="stBfCount" style="margin-top:6px">${esc(backfillCountText(14))}</div>
      <div class="hr" id="stSecVideo"></div>
      ${poseSettingsHtml()}
      <div class="hr"></div>
      <div class="eyebrow" id="stSecData" style="margin-bottom:8px">Data</div>
      <div class="sub" style="margin-bottom:10px">${S.workouts.length} workouts · ${S.checkins.length} check-ins · ${S.meets.length} meets · ${S.goals.length} goals</div>
      ${storageLine()}
      <div class="eyebrow" style="margin:4px 0 6px">Google Drive</div>
      ${syncLine()}
      <div class="row" style="gap:8px">
        <button class="btn sm grow" id="stExport">Export JSON</button>
        <button class="btn sm grow" id="stImport">Import JSON</button>
      </div>
      <button class="btn sm wide" id="stExportCsv" style="margin-top:9px">Export sets as CSV</button>
      <label class="row" style="gap:8px;margin-top:12px;font-size:13px"><input type="checkbox" id="stVbtRaw"${S.settings.vbtKeepRaw ? ' checked' : ''}> Bar-speed debug: keep raw sensor traces (last ${VBT_RAW_MAX} sets, this phone only)</label>
      <button class="btn sm wide ghost" id="stVbtRawExp" style="margin-top:6px">Export raw traces (${vbtRawList().length})</button>
      <div class="sub" style="margin-top:4px">One row per set, for spreadsheets. JSON is the full backup; either comes back in exactly.</div>
      ${hasFoodData() ? `<button class="btn sm wide" id="stFoodExport" style="margin-top:9px">Save old food log (${S.foods.length})…</button>` : ''}
      <button class="btn sm wide" id="stLiftoff" style="margin-top:9px">Import CSV (Ironlog, Strong, Hevy, FitNotes, Liftoff…)</button>
      ${liftoffImported().length ? `<button class="btn sm wide ghost" id="stUnimport" style="margin-top:9px">Remove imported sessions (${liftoffImported().length})…</button>` : ''}
      <button class="btn sm wide ghost" id="stCheck" style="margin-top:9px">Check exercise data</button>
      <div class="sub" style="margin-top:6px">Real training history — imported sessions count toward your PRs.</div>
      <button class="btn sm wide" id="stClear" style="margin-top:9px">Clear data…</button>
      <button class="btn sm danger wide" id="stWipe" style="margin-top:9px">Erase all data</button>
      <input type="file" id="stFile" accept="application/json" style="display:none">
      <div id="stImpUndo"></div>
      <input type="file" id="stCsvFile" accept=".csv,text/csv" style="display:none">
    `,
    foot: `<span class="muted mono" style="font-size:11px;margin-right:auto">v${APP_VERSION}</span>
      <button class="btn sm ghost" id="stHelp">Help</button>
      <button class="btn sm ghost" id="stNews">What's new</button>
      <button class="btn sm ghost" id="stUpdate">Check for update</button>
           <button class="btn primary" id="stSave">Save</button>`,
    onOpen: bg => {
      /* Applied and saved on the tap rather than on Save, because the point of
         a skin is seeing it — and because dismissing this modal by tapping the
         backdrop shouldn't silently undo a choice you can already see. */
      bg.querySelectorAll('#skinSeg button').forEach(b => b.onclick = () => {
        bg.querySelectorAll('#skinSeg button').forEach(x => x.classList.remove('on'));
        b.classList.add('on');
        S.settings.skin = b.dataset.sk;
        applySkin(S.settings.skin);
        save();
      });
      // saved on the tap, like the skin: a toggle you can hear shouldn't wait for Save
      bg.querySelectorAll('#restAutoSeg button').forEach(b => b.onclick = () => {
        bg.querySelectorAll('#restAutoSeg button').forEach(x => x.classList.toggle('on', x === b));
        S.settings.restAuto = b.dataset.v === '1';
        save();
      });
      const rn = $('#stRestNote', bg);
      if (rn) rn.onclick = () => {
        try {
          Promise.resolve(Notification.requestPermission()).then(p => {
            rn.disabled = true;
            rn.textContent = p === 'granted' ? 'Rest notifications on' : 'Notifications not allowed';
          });
        } catch (e) { /* old API shape */ }
      };
      [['#sndSeg', 'sound'], ['#vibSeg', 'vibrate']].forEach(([sel, k]) => bg.querySelectorAll(sel + ' button').forEach(b => b.onclick = () => {
        bg.querySelectorAll(sel + ' button').forEach(x => x.classList.toggle('on', x === b));
        S.settings[k] = b.dataset.v === '1';
        save();
        if (k === 'sound' && S.settings.sound) { Cue.unlock(); Cue.tick(); }
        if (k === 'vibrate' && S.settings.vibrate) Cue.buzz(80);
      }));
      let units = U();
      bg.querySelectorAll('#unitSeg button').forEach(b => b.onclick = () => {
        units = b.dataset.u;
        bg.querySelectorAll('#unitSeg button').forEach(x => x.classList.toggle('on', x === b));
      });
      $('#stPlanImport', bg).onclick = () => openPlanImport();
      $('#stKeyShow', bg).onclick = ev => {
        const k = $('#stKey', bg), on = k.type === 'password';
        k.type = on ? 'text' : 'password'; ev.target.textContent = on ? 'Hide' : 'Show'; ev.target.setAttribute('aria-pressed', on);
      };
      $('#stKeyTest', bg).onclick = async () => {
        const k = $('#stKey', bg).value.trim(), msg = $('#stKeyMsg', bg);
        if (!k) { msg.textContent = 'Enter a key first.'; return; }
        setAiKey(k);
        msg.textContent = 'Checking…';
        try {
          await aiCall({ feature: 'check', user: 'Reply with OK.', maxTokens: 1 });
          msg.textContent = '✓ Key works.';
        } catch (e) { msg.textContent = aiWhy(e); }
        $('#stAiUse', bg).innerHTML = aiUsageHtml(); wireAiUsage(bg);
      };
      wireAiUsage(bg);
      bg.querySelectorAll('#dbgSeg button').forEach(b => b.onclick = () => {
        bg.querySelectorAll('#dbgSeg button').forEach(x => x.classList.toggle('on', x === b));
        S.settings.debug = b.dataset.v === '1';
        if (!S.settings.debug) setCardioWhyLast(null);
        save(); render();
      });
      bg.querySelectorAll('#prEstSeg button').forEach(b => b.onclick = () => {
        bg.querySelectorAll('#prEstSeg button').forEach(x => x.classList.remove('on'));
        b.classList.add('on');
        S.settings.prCountEst = b.dataset.pe === '1';
        bust();
      });
      const pg = $('#stProgram', bg);
      if (pg) pg.onclick = () => { closeModal(); openProgram(); };
      bg.querySelectorAll('[data-oldprog]').forEach(b => b.onclick = () => {
        const id = b.dataset.oldprog;
        confirmDlg(`Remove the planned sessions left from ${programName(id)}? Sessions you've trained are kept.`,
          () => { const n = removeProgram(id); closeAllModals(); render(); toast(`${n} planned sessions removed`); },
          'Remove');
      });

      const addRow = (host, html) => { const d = document.createElement('div'); d.innerHTML = html; host.appendChild(d.firstElementChild); };
      const wireRm = () => bg.querySelectorAll('[data-brm],[data-prm]').forEach(b => b.onclick = () => b.closest('.row').remove());
      $('#stAddBar', bg).onclick = () => { addRow($('#stBars', bg), barRow(`n${Date.now()}`, { name: '', kg: 0, eq: '' })); wireRm(); };
      bg.querySelectorAll('[data-bpre]').forEach(b => b.onclick = () => {
        addRow($('#stBars', bg), barRow(`n${Date.now()}`, BAR_PRESETS[+b.dataset.bpre])); wireRm();
      });
      $('#stAddPlate', bg).onclick = () => { const k = `n${Date.now()}`; addRow($('#stPlates', bg),
        `<div class="row" style="gap:8px;margin-bottom:6px;align-items:center"><input type="number" step="0.25" inputmode="decimal" data-pk="${k}" style="width:82px" aria-label="Plate size (${U()})">
         <span class="sub">${U()} ×</span><input type="number" inputmode="numeric" data-pp="${k}" value="1" style="width:64px" aria-label="Pairs of this plate">
         <span class="sub grow">pairs</span><span style="width:34px"></span></div>`); };
      bg.querySelectorAll('[data-brm],[data-prm]').forEach(b => b.onclick = () => b.closest('.row').remove());

      const bfDays = $('#stBfDays', bg), bfCount = $('#stBfCount', bg);
      const refreshCount = () => { bfCount.textContent = backfillCountText(+bfDays.value); };
      bfDays.onchange = refreshCount;
      $('#stBackfill', bg).onclick = () => {
        const d = +bfDays.value;
        const c = plannedInWindow(d), n = c.ok;
        if (!n) return toast(c.rir ? `Nothing to mark done: ${c.rir === 1 ? 'the session in that window comes' : `all ${c.rir} sessions in that window come`} from a plan with no weights (RIR only), and would log every set at 0 kg` : 'No planned sessions in that window');
        confirmDlg(`Mark ${n} planned session${n === 1 ? '' : 's'} from the ${d} days up to yesterday as done, at the prescribed loads?`, () => {
          const c = backfillPlanned(d);
          closeAllModals(); render();
          toast(`${c} session${c === 1 ? '' : 's'} backfilled — edit any of them to correct the numbers`, 'green');
        }, 'Mark done');
      };
      $('#stExport', bg).onclick = () => { exportJSON(); refreshStorageLine(bg); };
      wirePoseSettings(bg);
      /* Settings runs to about six screens. The row at the top jumps to a
         section and puts focus there, so a screen reader lands on it too (00-D1). */
      bg.querySelectorAll('[data-stjump]').forEach(b => b.onclick = () => {
        const el = bg.querySelector('#' + b.dataset.stjump);
        if (!el) return;
        el.scrollIntoView({ block: 'start', behavior: window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches ? 'auto' : 'smooth' });
        el.setAttribute('tabindex', '-1');
        try { el.focus({ preventScroll: true }); } catch (e) { /* old browser */ }
      });
      $('#stVbtRaw', bg).onchange = ev => { S.settings.vbtKeepRaw = ev.target.checked; save(); toast(ev.target.checked ? 'Keeping raw traces from your next measured set' : 'Raw traces off — kept ones stay until exported or replaced'); };
      $('#stVbtRawExp', bg).onclick = () => exportVbtRaw();
      $('#stExportCsv', bg).onclick = () => { exportCSV(); refreshStorageLine(bg); };
      refreshSyncLine(bg);
      refreshStorageLine(bg);                                         // binds "Ask again"
      if (persist.state === 'unknown') storageStatus().then(() => refreshStorageLine(bg));
      const sfx = $('#stFoodExport', bg); if (sfx) sfx.onclick = () => { closeModal(); openFoodExport(); };
      $('#stImport', bg).onclick = () => $('#stFile', bg).click();
      $('#stFile', bg).onchange = e => {
        const f = e.target.files[0]; if (!f) return;
        importJSONFile(f);
        e.target.value = '';   // so picking the same file twice still fires
      };
      // the log an import replaced stays on the phone until it's put back or the next import
      importUndoInfo().then(o => {
        const host = $('#stImpUndo', bg);
        if (!o || !host) return;
        const c = logCounts(o.state);
        host.innerHTML = `<div class="row between" style="gap:10px;align-items:center;margin-top:9px">
          <div class="grow sub">A backup was imported ${esc(relTime(o.at))}. The log it replaced (${esc(logCountsLine(c))}) is still on this phone.</div>
          <button class="btn xs" id="stImpUndoGo">Undo import</button></div>`;
        $('#stImpUndoGo', bg).onclick = () => confirmDlg('Put back the log from before the import? What was imported, and anything logged since, is replaced by it.', () => undoImport(), 'Undo import');
      });
      $('#stLiftoff', bg).onclick = () => $('#stCsvFile', bg).click();
      $('#stCsvFile', bg).onchange = e => {
        const f = e.target.files[0]; if (!f) return;
        const rd = new FileReader();
        rd.onload = () => {
          closeAllModals();
          // Ironlog's own CSV comes back exactly; anything else is Liftoff's
          if (/^\uFEFF?format,/.test(rd.result) && rd.result.includes(CSV_FORMAT)) {
            try {
              const r = importIronlogCSV(rd.result);
              render();
              toast(`Imported ${r.added} session${r.added === 1 ? '' : 's'}${r.skipped ? ` · ${r.skipped} already here` : ''}`, 'green');
            } catch (err) { toast('Could not read that CSV'); }
          } else openLiftoffImport(rd.result);
        };
        rd.onerror = () => toast('Could not read that file');
        rd.readAsText(f);
        e.target.value = '';   // so picking the same file twice still fires
      };
      $('#stClear', bg).onclick = openClearData;
      $('#stCheck', bg).onclick = () => { closeModal(); openExerciseCheck(); };
      const ui = $('#stUnimport', bg); if (ui) ui.onclick = () => { closeModal(); openRemoveImport(); };
      $('#stUpdate', bg).onclick = () => checkForUpdate(false);
      $('#stNews', bg).onclick = () => { closeModal(); openWhatsNew(); };
      $('#stHelp', bg).onclick = () => { closeModal(); openHelp(); };
      $('#stProfile', bg).onclick = () => { closeModal(); openProfile(); };
      $('#stPlaces', bg).onclick = () => { closeModal(); openPlaces(); };
      $('#stWipe', bg).onclick = () => openEraseAll();
      $('#stSave', bg).onclick = () => {
        S.settings.units = units;
        const op = +$('#stOpener', bg).value;
        if (op >= 50 && op <= 100) S.settings.openerPct = op;
        setAiKey($('#stKey', bg).value.trim());
        const cap = parseFloat(String($('#stAiCap', bg).value).replace(',', '.'));
        if (cap >= 0 && cap <= 1000) S.settings.aiCap = Math.round(cap * 100) / 100;
        const pp = +$('#stPlatform', bg).value;
        if (pp >= 80 && pp <= 100) S.settings.platformPct = pp;
        const rm = parseTime($('#stRestMain', bg).value), ra = parseTime($('#stRestAcc', bg).value);
        if (rm && rm <= 1800) S.settings.restDefault = rm;
        if (ra && ra <= 1800) S.settings.restAccessory = ra;
        const rw = +$('#stRestWarn', bg).value;
        if (rw >= 0 && rw <= 60) S.settings.restWarn = Math.round(rw);

        // inventory: read the rows back, drop anything blank or nonsensical
        const nb = [...bg.querySelectorAll('[data-bn]')].map((el, i) => ({
          name: el.value.trim() || `Bar ${i + 1}`,
          kg: toKg(+bg.querySelector(`[data-bk="${el.dataset.bn}"]`).value || 0),
          eq: (bg.querySelector(`[data-be="${el.dataset.bn}"]`) || {}).value || '',
        })).filter(b => b.kg > 0).map(b => b.eq ? b : { name: b.name, kg: b.kg });
        if (nb.length) { S.settings.bars = nb; S.settings.barKg = nb[0].kg; }

        const np = [...bg.querySelectorAll('[data-pk]')].map(el => ({
          kg: toKg(+el.value || 0),
          pairs: Math.max(0, +bg.querySelector(`[data-pp="${el.dataset.pk}"]`).value || 0),
        })).filter(x => x.kg > 0 && x.pairs > 0).sort((x, y) => y.kg - x.kg);
        if (np.length) S.settings.plates = np;
        const col = +$('#stCollar', bg).value;
        if (col > 0) S.settings.collarKg = toKg(col); else delete S.settings.collarKg;
        save(); closeModal(); render(); toast('Settings saved', 'green');
      };
    },
  });
}


/* ============================================================
   EVENT WIRING
   ============================================================ */
function wire() {
  const v = $('#view');

  // generic nav
  v.querySelectorAll('[data-go]').forEach(b => b.onclick = () => go(b.dataset.go));
  v.querySelectorAll('[data-start-planned]').forEach(b => b.onclick = () => startPlanned(b.dataset.startPlanned));
  v.querySelectorAll('[data-miss]').forEach(b => b.onclick = () => openMissed(b.dataset.miss));
  v.querySelectorAll('[data-unmiss]').forEach(b => b.onclick = () => undoMiss(b.dataset.unmiss));
  v.querySelectorAll('[data-view-workout]').forEach(b => b.onclick = () => viewCompleted(b.dataset.viewWorkout));
  v.querySelectorAll('[data-edit-workout]').forEach(b => b.onclick = () => openEditWorkout(b.dataset.editWorkout));
  v.querySelectorAll('[data-edit-plan]').forEach(b => b.onclick = () => openPlanner(calSelected, b.dataset.editPlan));
  v.querySelectorAll('[data-del-workout]').forEach(b => b.onclick = () => confirmDlg('Delete this planned workout?', () => {
    S.workouts = S.workouts.filter(x => x.id !== b.dataset.delWorkout); save(); render();
  }));
  v.querySelectorAll('[data-repeat]').forEach(b => b.onclick = () => repeatWorkout(b.dataset.repeat));
  v.querySelectorAll('[data-edit-meet]').forEach(b => b.onclick = () => openMeet(b.dataset.editMeet));
  v.querySelectorAll('[data-exdetail]').forEach(b => b.onclick = () => openExDetail(b.dataset.exdetail));

  v.querySelectorAll('[data-goal]').forEach(b => b.onclick = () => openGoal(b.dataset.goal));
  v.querySelectorAll('[data-mobopen]').forEach(b => b.onclick = () => openMobility(b.dataset.mobopen, b.dataset.mobdate || today()));

  if (page === 'home') {
    { const r = $('#hmReview', v); if (r) r.onclick = () => openCoach('ask:review'); }
    const bn = $('#backupNow');
    if (bn) bn.onclick = !syncMeta().connected ? exportJSON : async () => {
      bn.disabled = true; bn.textContent = 'Syncing…';
      try { await driveSync(true); toast('Synced', 'green'); } catch (e) { toast(e.message || 'Sync failed'); }
      render();
    };
    const bl = $('#backupLater'); if (bl) bl.onclick = () => { S.settings.backupSnoozeUntil = Date.now() + BACKUP_SNOOZE; save(); render(); };
    $('#checkinBtn').onclick = () => openCheckin();
    const qs = $('#quickStart'); if (qs) qs.onclick = newBlank;
    $('#addGoal').onclick = () => openGoal();
    v.querySelectorAll('[data-meetday]').forEach(b => b.onclick = () => openMeetDay(b.dataset.meetday));
    if ($('#aboutCard')) {
      $('#aboutHide').onclick = () => { S.settings.aboutHidden = true; save(); render(); toast('Hidden — Help & FAQ can bring it back'); };
      $('#aboutNews').onclick = () => openWhatsNew();
      $('#aboutHelp').onclick = () => openHelp();
      const ai = $('#aboutInstall');
      if (ai) ai.onclick = async () => {
        const ev = installEvt; setInstallEvt(null);
        if (!ev) return render();
        ev.prompt();
        try { await ev.userChoice; } catch (e) { /* dismissed */ }
        render();
      };
    }
  }

  if (page === 'calendar') {
    $('#calPrev').onclick = () => { setCalCursor(new Date(calCursor.getFullYear(), calCursor.getMonth() - 1, 1)); render(); };
    $('#calNext').onclick = () => { setCalCursor(new Date(calCursor.getFullYear(), calCursor.getMonth() + 1, 1)); render(); };
    v.querySelectorAll('[data-day]').forEach(b => b.onclick = () => {
      setCalSelected(b.dataset.day);
      const d = parseISO(calSelected);
      if (d.getMonth() !== calCursor.getMonth()) setCalCursor(new Date(d.getFullYear(), d.getMonth(), 1));
      render();
    });
    $('#planDay').onclick = () => openPlanner(calSelected);
    $('#ciDay').onclick = () => openCheckin(calSelected);
    v.querySelectorAll('[data-meetday]').forEach(b => b.onclick = () => openMeetDay(b.dataset.meetday));
  }

  if (page === 'health') {
    wireBody(v);
    wireVitals(v);
    wireMobTests(v);
    wireFit(v);
    v.querySelectorAll('[data-hl]').forEach(b => b.onclick = () => { const c = $('#' + b.dataset.hl); if (c) c.scrollIntoView({ behavior: 'smooth', block: 'start' }); });
    v.querySelectorAll('[data-tool]').forEach(b => b.onclick = () => openTool(b.dataset.tool));
    $('#hlRecovery').onclick = () => { setAnalyticsTab('muscles'); go('analytics'); };
  }

  if (page === 'workout') {
    if (!S.active) {
      $('#startBlank').onclick = newBlank;
      { const ec = $('#emptyCoach'); if (ec) ec.onclick = () => openCoach(); }   // the empty Planned list offers the coach (00-D1)
      $('#startCardio').onclick = openCardioSetup;
      $('#startIntervals').onclick = openIntervalSetup;
      $('#startMobility').onclick = openMobilityPicker;
    } else if (S.active.kind === 'cardio') {
      wireCardio(v);
    } else {
      wireActive(v);
    }
  }

  if (page === 'analytics') {
    const q = $('#anQ');
    if (q) {
      q.oninput = () => {
        setAnalyticsQuery(q.value);
        const pos = q.selectionStart;
        render();
        const nq = $('#anQ'); if (nq) { nq.focus(); nq.setSelectionRange(pos, pos); }
      };
    }
    v.querySelectorAll('[data-sort]').forEach(b => b.onclick = () => { setAnalyticsSort(b.dataset.sort); render(); });
    v.querySelectorAll('[data-antab]').forEach(b => b.onclick = () => { setAnalyticsTab(b.dataset.antab); render(); window.scrollTo(0, 0); });
  v.querySelectorAll('[data-volm]').forEach(r => {
    r.onclick = () => openVolMuscle(r.dataset.volm);
    r.onkeydown = ev => { if (ev.key === 'Enter' || ev.key === ' ') { ev.preventDefault(); openVolMuscle(r.dataset.volm); } };
  });
    wireMuscleMap(v);
  }

  if (page === 'meets') {
    $('#addMeet').onclick = openAddEvent;
    const lt = $('#logTestBtn');
    if (lt) lt.onclick = openTestLog;
    v.querySelectorAll('[data-lockmeet]').forEach(b => b.onclick = () => {
    const mt = S.meets.find(x => x.id === b.dataset.lockmeet);
    if (!mt) return;
    mt.attemptsLocked = !mt.attemptsLocked;
    save(); render();
    toast(mt.attemptsLocked ? 'Attempts pinned to the plan' : 'Attempts following your tests', 'green');
  });
    $('#editPriority').onclick = openPriority;
    v.querySelectorAll('[data-meetday]').forEach(b => b.onclick = () => openMeetDay(b.dataset.meetday));
    v.querySelectorAll('[data-runin]').forEach(b => b.onclick = () => openBlocks(b.dataset.runin));
    v.querySelectorAll('[data-strat]').forEach(b => b.onclick = () => {
      const [id, k] = b.dataset.strat.split(':');
      const mt = S.meets.find(x => x.id === id);
      if (!mt) return;
      if (k === 'standard') delete mt.strategy; else mt.strategy = k;
      save(); render();
    });
  }

  // the rest loop runs on every page, so the end alert fires wherever you are
  if (S.active && S.active.rest && !restIv) restLoop();
  // a cardio session keeps coaching on every page, and keeps the screen on
  if (S.active && S.active.kind === 'cardio' && !cardioIv) { Awake.hold('cardio'); cardioLoop(); }

  // timer ticking only while a workout is live and visible
  clearInterval(tick);
  if (page === 'workout' && S.active) {
    setTick(setInterval(() => { const t = $('#timer'); if (t) t.textContent = elapsed(); else clearInterval(tick); }, 1000));
  }
}

/* ============================================================
   WINDOWS 98 SKIN

   The skin is paint: no view function knows it exists, and render() is not
   involved. What lives here is the chrome that has no counterpart in the
   default skin — a title bar, a menu bar and the LCD readout — which is
   mounted when the skin goes on and taken away again when it comes off.
   ============================================================ */
let skinTick = null;

function drawSkin(skin) {
  const s = skin === 'win98' ? 'win98' : 'ironlog';
  document.documentElement.dataset.skin = s;
  try { localStorage.setItem('ironlog.skin', s); } catch (e) {}

  /* The manifest's theme_color is read at install time and cannot follow a
     runtime toggle, but this meta is what actually tints the Android status
     bar on an open page. */
  const tc = document.querySelector('meta[name=theme-color]');
  if (tc) tc.content = s === 'win98' ? '#000080' : '#0d0f14';

  if (s === 'win98') mountChrome(); else unmountChrome();
}

function mountChrome() {
  if (document.getElementById('w98-title')) { lcdTick(); return; }   // idempotent: boot calls applySkin twice

  const title = document.createElement('div');
  title.id = 'w98-title';
  title.setAttribute('role', 'region');            // its text sits outside every landmark otherwise (axe "region")
  title.setAttribute('aria-label', 'Window title');
  title.innerHTML = `
    <span class="ic">▮</span>
    <span class="t">IRONLOG 98 — Strength Training Manager</span>
    <span class="wbtns">
      <button class="wbtn" id="w98Min" title="Collapse the window frame">_</button>
      <button class="wbtn" id="w98Max" title="Toggle full width">□</button>
      <button class="wbtn" id="w98Close" title="Close everything and go Home">✕</button>
    </span>`;

  const menu = document.createElement('div');
  menu.id = 'w98-menu';
  menu.innerHTML = W98_MENUS.map((m, i) => `
    <div class="m" data-mi="${i}">
      <button class="mlab"><u>${m.label[0]}</u>${esc(m.label.slice(1))}</button>
      <div class="mdrop">${m.items.map((it, j) =>
    it === '-' ? '<div class="sep"></div>' : `<button data-mi="${i}" data-ii="${j}">${esc(it[0])}</button>`).join('')}</div>
    </div>`).join('');

  const topbar = document.getElementById('topbar');
  document.body.insertBefore(title, topbar);
  document.body.insertBefore(menu, topbar);

  const lcd = document.createElement('div');
  lcd.id = 'w98-lcd';
  lcd.innerHTML = '<div class="clock" id="lcdClock"></div><div class="sets" id="lcdSets"></div>';
  topbar.insertBefore(lcd, topbar.querySelector('.tb-right'));

  wireChrome();
  lcdTick();
  if (!skinTick) skinTick = setInterval(lcdTick, 1000);
}

function unmountChrome() {
  if (skinTick) { clearInterval(skinTick); skinTick = null; }
  ['w98-title', 'w98-menu', 'w98-lcd'].forEach(id => {
    const el = document.getElementById(id);
    if (el) el.remove();
  });
  delete document.documentElement.dataset.w98Min;
  delete document.documentElement.dataset.w98Max;
}

/* Every item points at something the app already does. The menu is a second
   door onto existing functions, not a second implementation of anything. */
const W98_MENUS = [
  { label: 'File', items: [
    ['New workout', () => { closeAllModals(); go('workout'); }],
    ['Export JSON…', () => exportJSON()],
    ['Import JSON…', () => pickImportFile()],
    '-',
    ['Clear data…', () => openClearData()],
  ] },
  { label: 'View', items: [
    ['Home', () => go('home')],
    ['Calendar', () => go('calendar')],
    ['Train', () => go('workout')],
    ['Stats', () => go('analytics')],
    ['Health', () => go('health')],
    ['Events', () => go('meets')],
  ] },
  { label: 'Coach', items: [
    ['Coach…', () => openCoach()],
    ['My answers…', () => openCoach('answers')],
    ['Fitting test…', () => openFitTest('home')],
  ] },
  { label: 'Tools', items: [
    ['Tools…', () => openTools()],
    '-',
    ['Settings…', () => openSettings()],
    ['Profile…', () => openProfile()],
    '-',
    ['Check for update', () => checkForUpdate(false)],
  ] },
  { label: 'Help', items: [
    ['Help & FAQ…', () => openHelp()],
    ["What's new…", () => openWhatsNew()],
    ['About Ironlog 98', () => aboutDlg()],
    '-',
    ['Back to the Ironlog skin', () => { S.settings.skin = 'ironlog'; save(); applySkin('ironlog'); }],
  ] },
];

function closeMenus() {
  document.querySelectorAll('#w98-menu .m.open').forEach(m => m.classList.remove('open'));
}

function wireChrome() {
  const root = document.documentElement;

  /* What these three can honestly do. A page cannot close a tab it did not
     open, and an installed PWA has no window to minimise, so rather than fake
     an OS they are wired to the nearest useful thing: get the frame out of the
     way, drop the reading-width cap, and clear the screen back to Home. */
  document.getElementById('w98Min').onclick = () => {
    if (root.dataset.w98Min) delete root.dataset.w98Min; else root.dataset.w98Min = '1';
  };
  document.getElementById('w98Max').onclick = () => {
    if (root.dataset.w98Max) delete root.dataset.w98Max; else root.dataset.w98Max = '1';
  };
  document.getElementById('w98Close').onclick = () => {
    closeAllModals(); closeMenus(); go('home'); toast('Nothing to close — this is the whole program');
  };

  document.querySelectorAll('#w98-menu .mlab').forEach(lab => lab.onclick = e => {
    e.stopPropagation();
    const m = lab.parentElement, was = m.classList.contains('open');
    closeMenus();
    if (!was) m.classList.add('open');
  });
  document.querySelectorAll('#w98-menu .mdrop button').forEach(b => b.onclick = e => {
    e.stopPropagation();
    closeMenus();
    W98_MENUS[+b.dataset.mi].items[+b.dataset.ii][1]();
  });
  document.addEventListener('click', closeMenus);
}

/* The readout. Same self-cancelling idiom as the workout timer: if the node has
   gone, so has the skin, and the interval goes with it. */
function lcdTick() {
  const c = document.getElementById('lcdClock');
  if (!c) { if (skinTick) { clearInterval(skinTick); skinTick = null; } return; }
  const d = new Date();
  const dow = ['SUN', 'MON', 'TUE', 'WED', 'THU', 'FRI', 'SAT'][d.getDay()];
  const p = n => String(n).padStart(2, '0');
  c.innerHTML = `<span class="dow">${dow}</span>${p(d.getHours())}:${p(d.getMinutes())}:${p(d.getSeconds())}`;

  const el = document.getElementById('lcdSets');
  if (!el) return;
  /* A readout is decoration. It runs once a second and it runs during boot, so
     it is never allowed to be the thing that takes the log down — if the totals
     cannot be computed, say so in the panel and let the rest of the app say why
     in the console. */
  let t = null;
  try { t = liveTotals(); } catch (err) { console.warn('lcd totals', err); el.className = 'sets'; el.textContent = '— — —'; return; }
  el.className = 'sets' + (t ? ' live' : '');
  el.textContent = t ? `${t.setsDone}/${t.setsTotal} SETS · ${wt(t.vol, 0)}` : 'NO SESSION';
}

function aboutDlg() {
  modal({
    title: 'About Ironlog 98',
    body: `<div style="text-align:center;padding:6px 0 4px">
        <div style="font-size:22px;font-weight:800;letter-spacing:.06em">IRONLOG<span style="color:#b00000"> 98</span></div>
        <div class="sub" style="margin-top:4px">Strength Training Manager</div>
        <div class="sub" style="margin-top:10px">Version ${esc(APP_VERSION)}</div>
      </div>
      <div class="hr"></div>
      <div class="sub">A skin, nothing more — every number, PR and session is the same
      underneath. Settings → Skin puts it back.</div>`,
    foot: `<button class="btn primary wide" data-close>OK</button>`,
  });
}

/* The kit's render() and applySkin() call these: ui.js draws the pages and the 98 chrome. */
shell.render = renderPage;
shell.applySkin = drawSkin;
